/**
 * UI99 — Tactile Velvet Accordion Component (Build 02.2)
 * Dual-theme (Obsidian Dark / Porcelain Light) with Radix UI WAI-ARIA keyboard navigation and smooth height animation.
 */

import React from 'react';
import * as AccordionPrimitive from '@radix-ui/react-accordion';
import { ChevronDown } from 'lucide-react';
import { cn } from '../../lib/utils';
import { useIsDark } from './theme';

export interface AccordionItemProps {
  id: string;
  title: string;
  subtitle?: string;
  icon?: React.ReactNode;
  children: React.ReactNode;
}

export interface AccordionProps {
  items: AccordionItemProps[];
  defaultOpenId?: string;
  allowMultiple?: boolean;
  className?: string;
}

export function Accordion({
  items,
  defaultOpenId,
  allowMultiple = false,
  className = '',
}: AccordionProps) {
  const isDark = useIsDark();

  if (allowMultiple) {
    return (
      <AccordionPrimitive.Root
        type="multiple"
        defaultValue={defaultOpenId ? [defaultOpenId] : undefined}
        className={cn(
          'rounded-2xl border divide-y overflow-hidden transition-colors',
          isDark
            ? 'bg-[#0E0E14] border-white/[0.04] divide-white/[0.04]'
            : 'bg-white border-black/[0.06] divide-black/[0.06]',
          className
        )}
      >
        {items.map((item) => (
          <AccordionPrimitive.Item
            key={item.id}
            value={item.id}
            className="border-b last:border-b-0 border-inherit"
          >
            <AccordionPrimitive.Header className="flex">
              <AccordionPrimitive.Trigger
                className={cn(
                  'w-full px-4 py-3.5 flex items-center justify-between gap-3 text-left rtl:text-right transition-colors cursor-pointer select-none outline-none focus-ui99-inset',
                  isDark ? 'hover:bg-white/[0.02]' : 'hover:bg-black/[0.02]',
                  '[&[data-state=open]>div>svg]:rotate-180'
                )}
              >
                <div className="flex items-center gap-3 min-w-0">
                  {item.icon && (
                    <span className={isDark ? 'text-zinc-400' : 'text-zinc-600'}>
                      {item.icon}
                    </span>
                  )}
                  <div className="min-w-0">
                    <h4
                      className={cn(
                        'text-xs sm:text-sm font-semibold tracking-tight truncate',
                        isDark ? 'text-[#EDEDEF]' : 'text-zinc-900'
                      )}
                    >
                      {item.title}
                    </h4>
                    {item.subtitle && (
                      <p className="text-[11px] text-zinc-500 truncate mt-0.5">
                        {item.subtitle}
                      </p>
                    )}
                  </div>
                </div>

                <div className="shrink-0 text-zinc-400">
                  <ChevronDown className="w-4 h-4 transition-transform duration-200" />
                </div>
              </AccordionPrimitive.Trigger>
            </AccordionPrimitive.Header>

            <AccordionPrimitive.Content
              className={cn(
                'overflow-hidden text-xs sm:text-sm transition-all',
                'data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down'
              )}
            >
              <div
                className={cn(
                  'px-4 pb-4 pt-1 leading-relaxed',
                  isDark ? 'text-[#8E8E98]' : 'text-zinc-600'
                )}
              >
                {item.children}
              </div>
            </AccordionPrimitive.Content>
          </AccordionPrimitive.Item>
        ))}
      </AccordionPrimitive.Root>
    );
  }

  return (
    <AccordionPrimitive.Root
      type="single"
      defaultValue={defaultOpenId}
      collapsible
      className={cn(
        'rounded-2xl border divide-y overflow-hidden transition-colors',
        isDark
          ? 'bg-[#0E0E14] border-white/[0.04] divide-white/[0.04]'
          : 'bg-white border-black/[0.06] divide-black/[0.06]',
        className
      )}
    >
      {items.map((item) => (
        <AccordionPrimitive.Item
          key={item.id}
          value={item.id}
          className="border-b last:border-b-0 border-inherit"
        >
          <AccordionPrimitive.Header className="flex">
            <AccordionPrimitive.Trigger
              className={cn(
                'w-full px-4 py-3.5 flex items-center justify-between gap-3 text-left rtl:text-right transition-colors cursor-pointer select-none outline-none focus-visible:ring-2 focus-visible:ring-emerald-500/50',
                isDark ? 'hover:bg-white/[0.02]' : 'hover:bg-black/[0.02]',
                '[&[data-state=open]>div>svg]:rotate-180'
              )}
            >
              <div className="flex items-center gap-3 min-w-0">
                {item.icon && (
                  <span className={isDark ? 'text-zinc-400' : 'text-zinc-600'}>
                    {item.icon}
                  </span>
                )}
                <div className="min-w-0">
                  <h4
                    className={cn(
                      'text-xs sm:text-sm font-semibold tracking-tight truncate',
                      isDark ? 'text-[#EDEDEF]' : 'text-zinc-900'
                    )}
                  >
                    {item.title}
                  </h4>
                  {item.subtitle && (
                    <p className="text-[11px] text-zinc-500 truncate mt-0.5">
                      {item.subtitle}
                    </p>
                  )}
                </div>
              </div>

              <div className="shrink-0 text-zinc-400">
                <ChevronDown className="w-4 h-4 transition-transform duration-200" />
              </div>
            </AccordionPrimitive.Trigger>
          </AccordionPrimitive.Header>

          <AccordionPrimitive.Content
            className={cn(
              'overflow-hidden text-xs sm:text-sm transition-all',
              'data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down'
            )}
          >
            <div
              className={cn(
                'px-4 pb-4 pt-1 leading-relaxed',
                isDark ? 'text-[#8E8E98]' : 'text-zinc-600'
              )}
            >
              {item.children}
            </div>
          </AccordionPrimitive.Content>
        </AccordionPrimitive.Item>
      ))}
    </AccordionPrimitive.Root>
  );
}

/**
 * UI99 — ActivityFeed Component
 * Real-time event and audit stream with actor avatars, timestamps, and commit diff tags.
 */

import React from 'react';
import { GitCommit, CheckCircle2, MessageSquare, Plus, ArrowUpRight, Flame } from 'lucide-react';
import { cn } from '../../lib/utils';
import { Avatar } from './Button';
import { PriorityBadge, StatusBadge } from './Badge';

export interface ActivityEvent {
  id: string;
  actor: { name: string; avatar?: string };
  action: 'committed' | 'resolved' | 'commented' | 'created' | 'cycled';
  target: string;
  timestamp: string;
  details?: string;
}

export interface ActivityFeedProps {
  events?: ActivityEvent[];
  className?: string;
}

const DEFAULT_EVENTS: ActivityEvent[] = [
  {
    id: '1',
    actor: { name: 'Alex Mercer', avatar: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=64&h=64&fit=crop&crop=faces' },
    action: 'resolved',
    target: 'UI-101 (Migrate core tokens to Velvet Obsidian)',
    timestamp: '4m ago',
    details: 'Validated 100% WCAG AAA contrast in Dark & Light palettes.',
  },
  {
    id: '2',
    actor: { name: 'Sarah Connor', avatar: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=64&h=64&fit=crop&crop=faces' },
    action: 'committed',
    target: 'feat(ui): add 16 new master primitives to kit export',
    timestamp: '18m ago',
    details: 'Added ColorPicker, SignaturePad, TreeView, DiffViewer, TerminalEmulator.',
  },
  {
    id: '3',
    actor: { name: 'Elena Rostova', avatar: 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=64&h=64&fit=crop&crop=faces' },
    action: 'commented',
    target: 'UI-103 (Keyboard hotkeys documentation)',
    timestamp: '1h ago',
    details: '"The J/K selection feels extremely responsive like desktop software."',
  },
];

export function ActivityFeed({ events = DEFAULT_EVENTS, className }: ActivityFeedProps) {
  const getActionMeta = (action: ActivityEvent['action']) => {
    switch (action) {
      case 'resolved':
        return { icon: CheckCircle2, color: 'text-emerald-500 bg-emerald-500/10' };
      case 'committed':
        return { icon: GitCommit, color: 'text-blue-500 bg-blue-500/10' };
      case 'commented':
        return { icon: MessageSquare, color: 'text-purple-500 bg-purple-500/10' };
      case 'created':
        return { icon: Plus, color: 'text-amber-500 bg-amber-500/10' };
      case 'cycled':
        return { icon: Flame, color: 'text-rose-500 bg-rose-500/10' };
    }
  };

  return (
    <div
      className={cn(
        'p-4 rounded-3xl bg-white dark:bg-[#0B0C11] border border-black/[0.06] dark:border-white/[0.04]',
        'flex flex-col gap-4 shadow-sm w-full',
        className
      )}
    >
      <div className="flex items-center justify-between pb-2 border-b border-black/[0.04] dark:border-white/[0.03]">
        <h4 className="text-xs font-semibold text-zinc-900 dark:text-white uppercase tracking-wider font-mono">
          Live Activity Stream
        </h4>
        <span className="text-[10px] font-mono text-zinc-400">Real-time sync</span>
      </div>

      <div className="flex flex-col gap-4 relative">
        <div className="absolute top-3 bottom-3 left-4 w-[1px] bg-zinc-200 dark:bg-white/[0.06] -z-0" />

        {events.map((evt) => {
          const meta = getActionMeta(evt.action);
          const Icon = meta.icon;

          return (
            <div key={evt.id} className="flex items-start gap-3 relative z-10">
              <Avatar
                src={evt.actor.avatar}
                alt={evt.actor.name}
                size="sm"
                className="shrink-0 ring-2 ring-white dark:ring-[#0B0C11]"
              />

              <div className="flex-1 flex flex-col gap-1 min-w-0">
                <div className="flex flex-wrap items-center gap-1.5 text-xs">
                  <span className="font-semibold text-zinc-900 dark:text-white truncate">
                    {evt.actor.name}
                  </span>
                  <span className="text-zinc-500 dark:text-zinc-400">{evt.action}</span>
                  <span className="font-medium text-zinc-800 dark:text-zinc-200 truncate max-w-[200px] sm:max-w-none">
                    {evt.target}
                  </span>
                  <span className="text-[10px] text-zinc-400 ml-auto font-mono">
                    {evt.timestamp}
                  </span>
                </div>

                {evt.details && (
                  <p className="text-xs text-zinc-500 dark:text-zinc-400 bg-zinc-50 dark:bg-[#131318] p-2 rounded-xl border border-black/[0.03] dark:border-white/[0.03]">
                    {evt.details}
                  </p>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/**
 * UI99 — Alert (Wave A)
 * Static callout with severity variants + cva matrix, icon/title/description
 * slots, role="alert" when the destructive variant is used.
 */

import React from 'react';
import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from '../../lib/utils';

export const alertVariants = cva(
  'relative w-full flex gap-3 items-start rounded-2xl border p-4 text-sm tracking-tight',
  {
    variants: {
      variant: {
        default:
          'bg-(--bg-sunken) border-(--border-subtle) text-(--text-primary)',
        info: 'bg-blue-500/[0.06] dark:bg-blue-500/[0.08] border-blue-500/20 text-blue-800 dark:text-blue-300',
        success:
          'bg-emerald-500/[0.06] dark:bg-emerald-500/[0.08] border-emerald-500/20 text-emerald-800 dark:text-emerald-300',
        warning:
          'bg-amber-500/[0.06] dark:bg-amber-500/[0.08] border-amber-500/25 text-amber-800 dark:text-amber-300',
        destructive:
          'bg-rose-500/[0.06] dark:bg-rose-500/[0.08] border-rose-500/25 text-rose-800 dark:text-rose-300',
      },
    },
    defaultVariants: { variant: 'default' },
  }
);

export interface AlertProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof alertVariants> {
  icon?: React.ReactNode;
  title?: string;
}

export function Alert({ variant, icon, title, className, children, ...props }: AlertProps) {
  return (
    <div
      role={variant === 'destructive' ? 'alert' : undefined}
      className={cn(alertVariants({ variant }), className)}
      {...props}
    >
      {icon && <span className="mt-0.5 shrink-0 [&_svg]:size-4">{icon}</span>}
      <div className="space-y-1 min-w-0">
        {title && <div className="font-semibold leading-snug">{title}</div>}
        <div className="text-[13px] leading-relaxed opacity-90">{children}</div>
      </div>
    </div>
  );
}

/**
 * UI99 — AlertDialog (Wave B)
 * Radix alert-dialog: interruptive confirmation with destructive CTA.
 * Cannot be dismissed by overlay click — by design (WCAG-protected flow).
 */

import React from 'react';
import * as AlertDialogPrimitive from '@radix-ui/react-alert-dialog';
import type { VariantProps } from 'class-variance-authority';
import { cn } from '../../lib/utils';
import { buttonVariants } from './Button';

type ButtonVariantProps = VariantProps<typeof buttonVariants>;

export function AlertDialog({
  ...props
}: React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Root>) {
  return <AlertDialogPrimitive.Root {...props} />;
}
AlertDialog.displayName = 'AlertDialog';

export function AlertDialogTrigger({
  ...props
}: React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Trigger>) {
  return <AlertDialogPrimitive.Trigger {...props} />;
}
AlertDialogTrigger.displayName = 'AlertDialogTrigger';

export function AlertDialogPortal({
  ...props
}: React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Portal>) {
  return <AlertDialogPrimitive.Portal {...props} />;
}
AlertDialogPortal.displayName = 'AlertDialogPortal';

export function AlertDialogOverlay({
  className = '',
  ...props
}: React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Overlay>) {
  return (
    <AlertDialogPrimitive.Overlay
      className={cn(
        'fixed inset-0 z-50 bg-black/40 backdrop-blur-[2px]',
        'data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=closed]:animate-out data-[state=closed]:fade-out-0',
        className
      )}
      {...props}
    />
  );
}
AlertDialogOverlay.displayName = 'AlertDialogOverlay';

export function AlertDialogContent({
  className = '',
  ...props
}: React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Content>) {
  return (
    <AlertDialogPortal>
      <AlertDialogOverlay />
      <AlertDialogPrimitive.Content
        className={cn(
          'fixed left-1/2 top-1/2 z-50 w-full max-w-lg -translate-x-1/2 -translate-y-1/2 rounded-3xl border border-white/[0.03] bg-(--bg-elevated) p-6 shadow-[0_24px_56px_-10px_rgba(0,0,0,0.75)] focus:outline-none',
          'data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95',
          className
        )}
        {...props}
      />
    </AlertDialogPortal>
  );
}
AlertDialogContent.displayName = 'AlertDialogContent';

export function AlertDialogHeader({ className = '', ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('space-y-2', className)} {...props} />;
}
AlertDialogHeader.displayName = 'AlertDialogHeader';

export function AlertDialogFooter({ className = '', ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn('flex flex-col-reverse sm:flex-row sm:justify-end gap-2 pt-4', className)}
      {...props}
    />
  );
}
AlertDialogFooter.displayName = 'AlertDialogFooter';

export function AlertDialogTitle({
  className = '',
  ...props
}: React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Title>) {
  return (
    <AlertDialogPrimitive.Title
      className={cn('text-base font-bold tracking-tight text-zinc-950 dark:text-white', className)}
      {...props}
    />
  );
}
AlertDialogTitle.displayName = 'AlertDialogTitle';

export function AlertDialogDescription({
  className = '',
  ...props
}: React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Description>) {
  return (
    <AlertDialogPrimitive.Description
      className={cn('text-xs leading-relaxed text-(--text-secondary)', className)}
      {...props}
    />
  );
}
AlertDialogDescription.displayName = 'AlertDialogDescription';

export function AlertDialogAction({
  className = '',
  variant = 'primary',
  ...props
}: React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Action> &
  Pick<ButtonVariantProps, 'variant'>) {
  return (
    <AlertDialogPrimitive.Action
      className={cn(buttonVariants({ variant, size: 'md' }), 'min-h-[44px]', className)}
      {...props}
    />
  );
}
AlertDialogAction.displayName = 'AlertDialogAction';

export function AlertDialogCancel({
  className = '',
  ...props
}: React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Cancel>) {
  return (
    <AlertDialogPrimitive.Cancel
      className={cn(buttonVariants({ variant: 'outline', size: 'md' }), 'min-h-[44px]', className)}
      {...props}
    />
  );
}
AlertDialogCancel.displayName = 'AlertDialogCancel';

/**
 * UI99 — AspectRatio (Wave A)
 * Radix aspect-ratio box for media that must not shift layout while loading.
 */

import * as AspectRatioPrimitive from '@radix-ui/react-aspect-ratio';

export function AspectRatio({
  ...props
}: React.ComponentPropsWithoutRef<typeof AspectRatioPrimitive.Root>) {
  return <AspectRatioPrimitive.Root {...props} />;
}
AspectRatio.displayName = 'AspectRatio';

/**
 * UI99 — AudioPlayer Component
 * Velvet waveform audio player with timecode, scrubbable progress, volume, and playback controls.
 */

import React, { useState, useEffect } from 'react';
import { Play, Pause, Volume2, VolumeX, RotateCcw, RotateCw, Music } from 'lucide-react';
import { cn } from '../../lib/utils';

export interface AudioPlayerProps {
  title?: string;
  artist?: string;
  durationSec?: number;
  className?: string;
}

export function AudioPlayer({
  title = 'Obsidian Ambient Frequency',
  artist = 'UI99 Soundscapes',
  durationSec = 184,
  className,
}: AudioPlayerProps) {
  const [playing, setPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(42);
  const [muted, setMuted] = useState(false);
  const [volume, setVolume] = useState(80);

  useEffect(() => {
    let timer: any;
    if (playing) {
      timer = setInterval(() => {
        setCurrentTime((prev) => (prev >= durationSec ? 0 : prev + 1));
      }, 1000);
    }
    return () => clearInterval(timer);
  }, [playing, durationSec]);

  const formatTime = (sec: number) => {
    const mins = Math.floor(sec / 60);
    const secs = Math.floor(sec % 60);
    return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
  };

  const progressPct = (currentTime / durationSec) * 100;

  // Waveform bars simulation
  const bars = [
    30, 45, 60, 35, 75, 90, 60, 40, 55, 80, 100, 70, 50, 65, 85, 95, 60, 40, 70, 85,
    50, 35, 60, 80, 100, 75, 45, 65, 80, 50, 40, 70, 90, 65, 45, 30, 55, 75, 85, 60,
  ];

  return (
    <div
      role="group"
      aria-label={`Audio player: ${title} by ${artist}`}
      className={cn(
        'p-4 rounded-3xl bg-white dark:bg-[#0B0C11] border border-black/[0.06] dark:border-white/[0.04]',
        'shadow-[0_16px_36px_-8px_rgba(0,0,0,0.5)] flex flex-col gap-3 w-full max-w-md',
        className
      )}
    >
      {/* Title & Info */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-500">
            <Music className="w-5 h-5" />
          </div>
          <div>
            <h5 className="text-xs font-semibold text-zinc-900 dark:text-white truncate">
              {title}
            </h5>
            <p className="text-[11px] text-zinc-500 dark:text-zinc-400 truncate">
              {artist}
            </p>
          </div>
        </div>

        <span className="text-[11px] font-mono text-zinc-400">
          {formatTime(currentTime)} / {formatTime(durationSec)}
        </span>
      </div>

      {/* Simulated Waveform Visualization — scrubber */}
      <div
        role="slider"
        tabIndex={0}
        aria-label="Seek position"
        aria-valuemin={0}
        aria-valuemax={durationSec}
        aria-valuenow={Math.round(currentTime)}
        aria-valuetext={`${formatTime(currentTime)} of ${formatTime(durationSec)}`}
        onKeyDown={(e) => {
          if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
            e.preventDefault();
            const delta = e.key === 'ArrowLeft' ? -10 : 10;
            setCurrentTime((prev) => Math.min(durationSec, Math.max(0, prev + delta)));
          }
        }}
        className="flex items-end justify-between h-10 gap-1 px-1 cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500/60 rounded-lg"
        onClick={(e) => {
          const rect = e.currentTarget.getBoundingClientRect();
          const clickX = e.clientX - rect.left;
          const newPct = clickX / rect.width;
          setCurrentTime(Math.floor(newPct * durationSec));
        }}
      >
        {bars.map((barHeight, idx) => {
          const barPct = (idx / bars.length) * 100;
          const isPassed = barPct <= progressPct;

          return (
            <div
              key={idx}
              className={cn(
                'flex-1 rounded-full transition-all duration-150',
                isPassed
                  ? 'bg-zinc-900 dark:bg-emerald-400'
                  : 'bg-zinc-200 dark:bg-white/[0.08]'
              )}
              style={{ height: `${barHeight}%` }}
            />
          );
        })}
      </div>

      {/* Control Bar */}
      <div className="flex items-center justify-between pt-1 border-t border-black/[0.04] dark:border-white/[0.03]">
        <div className="flex items-center gap-1">
          <button
            type="button"
            onClick={() => setCurrentTime((prev) => Math.max(0, prev - 10))}
            aria-label="Rewind 10 seconds"
            className="p-1.5 rounded-lg text-zinc-400 hover:text-zinc-900 dark:hover:text-white transition-colors"
          >
            <RotateCcw className="w-3.5 h-3.5" />
          </button>

          <button
            type="button"
            onClick={() => setPlaying(!playing)}
            aria-label={playing ? 'Pause' : 'Play'}
            aria-pressed={playing}
            className="w-9 h-9 rounded-full bg-zinc-900 dark:bg-white text-white dark:text-black flex items-center justify-center shadow-md active:scale-95 transition-transform"
          >
            {playing ? <Pause className="w-4 h-4 fill-current" /> : <Play className="w-4 h-4 fill-current ml-0.5" />}
          </button>

          <button
            type="button"
            onClick={() => setCurrentTime((prev) => Math.min(durationSec, prev + 10))}
            aria-label="Forward 10 seconds"
            className="p-1.5 rounded-lg text-zinc-400 hover:text-zinc-900 dark:hover:text-white transition-colors"
          >
            <RotateCw className="w-3.5 h-3.5" />
          </button>
        </div>

        {/* Volume */}
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => setMuted(!muted)}
            aria-label={muted ? 'Unmute' : 'Mute'}
            aria-pressed={muted}
            className="text-zinc-400 hover:text-zinc-900 dark:hover:text-white transition-colors"
          >
            {muted || volume === 0 ? <VolumeX className="w-4 h-4" /> : <Volume2 className="w-4 h-4" />}
          </button>
          <input
            type="range"
            min={0}
            max={100}
            value={muted ? 0 : volume}
            onChange={(e) => {
              setVolume(Number(e.target.value));
              if (muted) setMuted(false);
            }}
            aria-label="Volume"
