              <div className="w-full flex flex-col gap-0.5 mt-1 overflow-hidden">
                {dayEvents.map((evt) => (
                  <span
                    key={evt.id}
                    className={cn(
                      'text-[9px] px-1 py-0.2 rounded font-medium truncate w-full border',
                      eventVariantStyles[evt.variant || 'emerald']
