/**
 * UI99 — Obsidian Liquid Glass (SOLG) Reusable Surfaces & Card Primitives (Build 02.2)
 * Authentic layered materials: Canvas -> Surface -> Elevated -> Liquid Glass
 * Dual-theme (Obsidian Dark / Porcelain Light) responsive.
 *
 * @token Surface ladder: canvas → `--bg-surface` → `--bg-card` →
 *   `--bg-elevated`; elevation steps add the deep-diffusion shadow profile
 *   (18px/40px −10px) and the specular top rim (`--border-specular`).
 *   Hover elevation lifts to `--bg-card-hover`.
 */

import React, { ReactNode, HTMLAttributes } from 'react';

export type SurfaceVariant =
  | 'surface'            // Primary container surface (#0E0E13 / white)
  | 'surfaceSecondary'   // Secondary container surface (#0B0C11 / #F8F8FA)
  | 'elevated'           // Elevated interactive surface (#131318 / white)
  | 'glass'              // Translucent liquid glass with blur
  | 'compact'            // Ultra-compact quiet list container
  | 'flat'               // Clean minimal container without shadow
  | 'outline';           // Pure hairline container

export interface SurfaceProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
  variant?: SurfaceVariant;
  rounded?: 'sm' | 'md' | 'lg' | 'xl' | '2xl' | '3xl' | 'full';
  padding?: 'none' | 'xs' | 'sm' | 'md' | 'lg' | 'xl';
  hoverable?: boolean;
  interactive?: boolean;
}

export function Surface({
  children,
  variant = 'surface',
  rounded = '2xl',
  padding = 'md',
  hoverable = false,
  interactive = false,
  className = '',
  ...props
}: SurfaceProps) {
  const roundMap = {
    sm: 'rounded-lg',
    md: 'rounded-xl',
    lg: 'rounded-2xl',
    xl: 'rounded-[22px]',
    '2xl': 'rounded-[26px]',
    '3xl': 'rounded-[32px]',
    full: 'rounded-full',
  }[rounded];

  const padMap = {
    none: 'p-0',
    xs: 'p-2 sm:p-2.5',
    sm: 'p-3 sm:p-3.5',
    md: 'p-4 sm:p-5',
    lg: 'p-5 sm:p-6',
    xl: 'p-6 sm:p-8',
  }[padding];

  const variantMap = {
    surface:
      'bg-(--bg-card) border border-black/[0.045] dark:border-white/[0.025] shadow-[0_4px_16px_rgba(0,0,0,0.03)] dark:shadow-[inset_0_1px_0_0_rgba(255,255,255,0.035),0_12px_32px_-8px_rgba(0,0,0,0.6)]',
    surfaceSecondary:
      'bg-[#F8F8FA] dark:bg-(--bg-surface) border border-black/[0.035] dark:border-white/[0.02] shadow-[inset_0_1px_0_0_rgba(255,255,255,0.8)] dark:shadow-[inset_0_1px_0_0_rgba(255,255,255,0.025)]',
    elevated:
      'bg-(--bg-elevated) border border-(--border-hairline) shadow-[0_8px_28px_rgba(0,0,0,0.05)] dark:shadow-[inset_0_1px_0_0_rgba(255,255,255,0.045),0_16px_40px_-8px_rgba(0,0,0,0.65)]',
    glass:
      'bg-white/80 dark:bg-[#0C0D12]/60 backdrop-blur-2xl border border-(--border-hairline) shadow-[0_8px_24px_rgba(0,0,0,0.04)] dark:shadow-[inset_0_1px_0_0_rgba(255,255,255,0.035),0_16px_40px_-10px_rgba(0,0,0,0.6)]',
    compact:
      'bg-white/90 dark:bg-(--bg-surface) border border-black/[0.03] dark:border-white/[0.02] shadow-xs',
    flat:
      'bg-zinc-100/80 dark:bg-(--bg-surface)/80 border-transparent',
    outline:
      'bg-transparent border border-black/[0.08] dark:border-white/[0.035]',
  }[variant];

  const hoverStyle =
    hoverable || interactive
      ? 'transition-all duration-200 hover:-translate-y-0.5 hover:shadow-md dark:hover:shadow-[0_16px_36px_-6px_rgba(0,0,0,0.7)] cursor-pointer active:scale-[0.99]'
      : '';

  return (
    <div
      className={`relative ${roundMap} ${padMap} ${variantMap} ${hoverStyle} ${className}`}
      {...props}
    >
      {children}
    </div>
  );
}

