/**
 * UI99 — Carousel (Wave G)
 * Native scroll-snap carousel (no animation lib): arrow buttons + dot
 * indicators, keyboard accessible, respects 44px targets. RTL-safe via
 * logical scroll (scrollBy inline direction-agnostic amounts).
  * @token Dots/arrows resolve `--text-primary` active vs 15% foreground idle; arrows are outline buttons on `--border-strong`.
*/

import React, { useRef, useState, useEffect, useCallback } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { cn } from '../../lib/utils';
import { IconButton } from './Button';

export interface CarouselProps {
  children: React.ReactNode[];
  itemClassName?: string;
  label?: string;
  className?: string;
}

export function Carousel({ children, itemClassName = '', label = 'Carousel', className = '' }: CarouselProps) {
  const trackRef = useRef<HTMLDivElement>(null);
  const [activeIndex, setActiveIndex] = useState(0);
  const count = React.Children.count(children);

  const scrollToIndex = useCallback(
    (index: number) => {
      const clamped = Math.max(0, Math.min(index, count - 1));
      const track = trackRef.current;
      if (!track) return;
      const child = track.children[clamped] as HTMLElement | undefined;
      if (child) track.scrollTo({ left: child.offsetLeft - track.offsetLeft, behavior: 'smooth' });
      setActiveIndex(clamped);
    },
    [count]
  );

  useEffect(() => {
    const track = trackRef.current;
    if (!track) return;
    const onScroll = () => {
      const child = track.children[0] as HTMLElement | undefined;
      if (!child) return;
      const step = child.offsetWidth + 16;
      setActiveIndex(Math.round(track.scrollLeft / step));
    };
    track.addEventListener('scroll', onScroll, { passive: true });
    return () => track.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <div className={cn('relative', className)} role="region" aria-label={label} aria-roledescription="carousel">
      <div
        ref={trackRef}
        className="flex gap-4 overflow-x-auto scroll-smooth no-scrollbar snap-x snap-mandatory pb-1"
      >
        {React.Children.map(children, (child, i) => (
          <div key={i} className={cn('snap-start shrink-0', itemClassName)}>
            {child}
          </div>
        ))}
      </div>

      <div className="mt-3 flex items-center justify-between">
        <div className="flex items-center gap-1.5" role="tablist" aria-label={`${label} position`}>
          {Array.from({ length: count }).map((_, i) => (
            <button
              key={i}
              type="button"
              role="tab"
              aria-selected={i === activeIndex}
              aria-label={`Go to slide ${i + 1}`}
              onClick={() => scrollToIndex(i)}
              className={cn(
                'h-2 rounded-full transition-all duration-200 cursor-pointer focus-visible:outline-none focus-ui99',
                i === activeIndex
                  ? 'w-5 bg-zinc-900 dark:bg-white'
                  : 'w-2 bg-black/[0.15] dark:bg-white/[0.15] hover:bg-black/[0.25] dark:hover:bg-white/[0.3]'
              )}
            />
          ))}
        </div>
        <div className="flex items-center gap-1.5">
          <IconButton
            icon={<ChevronLeft className="w-4 h-4" />}
            variant="outline"
            size="sm"
            label="Previous slide"
            onClick={() => scrollToIndex(activeIndex - 1)}
            disabled={activeIndex === 0}
          />
          <IconButton
            icon={<ChevronRight className="w-4 h-4" />}
            variant="outline"
            size="sm"
            label="Next slide"
            onClick={() => scrollToIndex(activeIndex + 1)}
            disabled={activeIndex >= count - 1}
          />
        </div>
      </div>
    </div>
  );
}

/**
 * UI99 — Tactile Checkbox & Radio Controls (Build 02.2)
 * Pixel-accurate, micro-spring check animations, dual-theme support.
 */

import React from 'react';
import { motion } from 'motion/react';
import { Check } from 'lucide-react';
import { useIsDark } from './theme';

export interface CheckboxProps {
  checked: boolean;
  onChange: (checked: boolean) => void;
  label?: React.ReactNode;
  description?: string;
  disabled?: boolean;
  size?: 'sm' | 'md';
  className?: string;
}

export function Checkbox({
  checked,
  onChange,
  label,
  description,
  disabled = false,
  size = 'md',
  className = '',
}: CheckboxProps) {
  const isDark = useIsDark();

  const boxSize = size === 'sm' ? 'w-4 h-4 rounded-md' : 'w-5 h-5 rounded-[7px]';
  const iconSize = size === 'sm' ? 'w-3 h-3' : 'w-3.5 h-3.5';

  return (
    <label
      className={`inline-flex items-start gap-2.5 cursor-pointer select-none ${
        disabled ? 'opacity-40 cursor-not-allowed' : ''
      } ${className}`}
    >
      {/* Native input for keyboard & assistive-tech support (WCAG 4.1.2) */}
      <input
        type="checkbox"
        className="peer sr-only"
        checked={checked}
        disabled={disabled}
        onChange={(e) => onChange(e.target.checked)}
      />
      <div
        className={`relative flex items-center justify-center shrink-0 mt-0.5 transition-all duration-150 peer-focus-visible:ring-2 peer-focus-visible:ring-emerald-500/55 ${boxSize} ${
          checked
            ? 'bg-emerald-500 text-white shadow-[0_0_10px_rgba(16,185,129,0.3)] border border-emerald-400'
            : isDark
            ? 'bg-[#15151C] border border-white/[0.1] peer-hover:border-white/[0.2]'
            : 'bg-zinc-100 border border-black/[0.12] peer-hover:border-black/[0.25]'
        }`}
      >
        {checked && (
          <motion.div
            initial={{ scale: 0.5, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            exit={{ scale: 0.5, opacity: 0 }}
            transition={{ type: 'spring', stiffness: 500, damping: 28 }}
          >
            <Check className={`${iconSize} stroke-[2.5]`} />
          </motion.div>
        )}
      </div>

      {(label || description) && (
        <div className="flex flex-col text-left rtl:text-right pt-0.5">
          {label && (
            <span
              className={`text-xs font-semibold tracking-tight leading-none ${
                isDark ? 'text-[#EDEDEF]' : 'text-zinc-900'
              }`}
            >
              {label}
            </span>
          )}
          {description && (
            <span
              className={`text-[11px] leading-snug mt-1 ${
                isDark ? 'text-[#8E8E98]' : 'text-zinc-500'
              }`}
            >
              {description}
            </span>
          )}
        </div>
      )}
    </label>
  );
}

export interface RadioProps {
  checked: boolean;
  onChange: () => void;
  label?: React.ReactNode;
  name?: string;
  disabled?: boolean;
  className?: string;
}

export function Radio({
  checked,
  onChange,
  label,
  name,
  disabled = false,
  className = '',
}: RadioProps) {
  const isDark = useIsDark();

  return (
    <label
      className={`inline-flex items-center gap-2.5 cursor-pointer select-none ${
        disabled ? 'opacity-40 cursor-not-allowed' : ''
      } ${className}`}
    >
      {/* Native input for keyboard & assistive-tech support (WCAG 4.1.2) */}
      <input
        type="radio"
        className="peer sr-only"
        checked={checked}
        disabled={disabled}
        name={name}
        onChange={onChange}
      />
      <div
        className={`w-4.5 h-4.5 rounded-full flex items-center justify-center shrink-0 transition-all peer-focus-visible:ring-2 peer-focus-visible:ring-emerald-500/55 ${
          checked
            ? 'border-2 border-emerald-500'
            : isDark
            ? 'border border-white/[0.12] bg-[#15151C] peer-hover:border-white/[0.25]'
            : 'border border-black/[0.15] bg-zinc-100 peer-hover:border-black/[0.3]'
        }`}
      >
        {checked && (
          <motion.div
            initial={{ scale: 0 }}
