      </div>

      {/* Preset Swatches Palette */}
      <div className="flex flex-wrap gap-1.5 pt-1 border-t border-black/[0.04] dark:border-white/[0.03]">
        {presetColors.map((preset) => (
          <button
            key={preset}
            type="button"
            onClick={() => handleColorChange(preset)}
            aria-label={`Select color ${preset}`}
            className={cn(
              'w-5 h-5 rounded-lg border border-black/10 dark:border-white/10 transition-all hover:scale-110 active:scale-95',
              color.toLowerCase() === preset.toLowerCase() && 'ring-2 ring-emerald-500 ring-offset-1 dark:ring-offset-[#0E0E14]'
            )}
            style={{ backgroundColor: preset }}
          />
        ))}
        {'EyeDropper' in (typeof window !== 'undefined' ? window : {}) && (
          <button
            type="button"
            onClick={handleEyeDropper}
            aria-label="Pick color from screen"
            className="w-5 h-5 rounded-lg border border-black/10 dark:border-white/10 flex items-center justify-center bg-zinc-100 dark:bg-white/[0.04] text-zinc-500 hover:text-zinc-900 dark:hover:text-white transition-colors"
          >
            <Pipette className="w-3 h-3" />
          </button>
        )}
      </div>
    </div>
  );
}

/**
 * UI99 — Combobox (Wave F)
 * Popover + cmdk filtered list with "both worlds" input (shadcn pattern):
 * filter-as-you-type, create-option affordance, 44px rows, full keyboard nav.
  * @token Panel resolves `--bg-elevated` + `--border-subtle`; rows hover via `--state-hover`; selected check rides `--text-primary`.
*/

import React, { useState } from 'react';
import * as PopoverPrimitive from '@radix-ui/react-popover';
import { Check, ChevronsUpDown } from 'lucide-react';
import { cn } from '../../lib/utils';
import { Command, CommandInput, CommandList, CommandEmpty, CommandGroup, CommandItem } from './Command';

export interface ComboboxOption {
  value: string;
  label: string;
  hint?: string;
}

export interface ComboboxProps {
  options: ComboboxOption[];
  /** Currently selected value; `null` = nothing selected. */
  value: string | null;
  onChange: (value: string | null) => void;
  placeholder?: string;
  searchPlaceholder?: string;
  /** Allow creating an option from free-typed text (Enter). */
  allowCreate?: boolean;
  emptyText?: string;
  disabled?: boolean;
  className?: string;
}

export function Combobox({
  options,
  value,
  onChange,
  placeholder = 'Select…',
  searchPlaceholder = 'Search…',
  allowCreate = false,
  emptyText = 'No results',
  disabled = false,
  className = '',
}: ComboboxProps) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState('');
  const selected = options.find((o) => o.value === value) ?? null;

  const exactMatch = options.some((o) => o.label.toLowerCase() === query.trim().toLowerCase());

  const createOption = () => {
    const label = query.trim();
    if (!label) return;
    onChange(label);
    setOpen(false);
    setQuery('');
  };

  return (
    <PopoverPrimitive.Root open={open} onOpenChange={setOpen}>
      <PopoverPrimitive.Trigger asChild>
        <button
          type="button"
          role="combobox"
          aria-expanded={open}
          disabled={disabled}
          className={cn(
            'inline-flex h-10 w-full items-center justify-between gap-2 rounded-xl border border-black/[0.07] bg-white px-3 text-sm',
            'dark:border-white/[0.07] dark:bg-[#131318]',
            'transition-colors hover:bg-(--state-hover)',
            'focus-visible:outline-none focus-ui99-inset cursor-pointer',
            'disabled:cursor-not-allowed disabled:opacity-45',
            className
          )}
        >
          <span className={cn('truncate', !selected && 'text-zinc-400 dark:text-[#8E8E98]')}>
            {selected ? selected.label : placeholder}
          </span>
          <ChevronsUpDown className="w-4 h-4 shrink-0 text-(--text-muted)" />
        </button>
      </PopoverPrimitive.Trigger>
      <PopoverPrimitive.Portal>
        <PopoverPrimitive.Content
          sideOffset={6}
          align="start"
          className="z-50 w-[var(--radix-popover-trigger-width)] rounded-2xl border border-black/[0.06] bg-white shadow-[0_20px_48px_-12px_rgba(0,0,0,0.7)] dark:border-white/[0.06] dark:bg-[#131318]"
        >
          <Command shouldFilter>
            <CommandInput placeholder={searchPlaceholder} onValueChange={setQuery} />
            <CommandList className="max-h-64">
              <CommandEmpty>{emptyText}</CommandEmpty>
              <CommandGroup>
                {options.map((option) => (
                  <CommandItem
                    key={option.value}
                    value={option.label}
                    onSelect={() => {
                      onChange(option.value);
                      setOpen(false);
                      setQuery('');
                    }}
                    className="min-h-[44px]"
                  >
                    <Check
                      className={cn(
                        'mr-2 w-4 h-4 shrink-0',
                        option.value === value ? 'opacity-100' : 'opacity-0'
                      )}
                    />
                    <span className="truncate">{option.label}</span>
                    {option.hint && (
                      <span className="ml-auto pl-2 text-[10px] font-mono text-(--text-muted)">
                        {option.hint}
                      </span>
                    )}
                  </CommandItem>
                ))}
              </CommandGroup>
              {allowCreate && query.trim() && !exactMatch && (
                <CommandGroup>
                  <CommandItem onSelect={createOption} className="min-h-[44px]">
                    <span className="mr-2 flex w-4 justify-center text-zinc-400">+</span>
                    Create “{query.trim()}”
                  </CommandItem>
                </CommandGroup>
              )}
            </CommandList>
          </Command>
        </PopoverPrimitive.Content>
      </PopoverPrimitive.Portal>
    </PopoverPrimitive.Root>
  );
}

