/**
 * UI99 — DiffViewer Component
 * Git diff side-by-side and unified line change viewer with additions and deletions.
 */

import React, { useState } from 'react';
import { Plus, Minus, GitCommit, Copy, Check } from 'lucide-react';
import { cn } from '../../lib/utils';
import { Button } from './Button';

export interface DiffLine {
  type: 'add' | 'delete' | 'normal';
  oldLineNumber?: number;
  newLineNumber?: number;
  content: string;
}

export interface DiffViewerProps {
  fileName?: string;
  lines: DiffLine[];
  className?: string;
}

export function DiffViewer({
  fileName = 'src/tokens/palette.ts',
  lines,
  className,
}: DiffViewerProps) {
  const [copied, setCopied] = useState(false);

  const additions = lines.filter((l) => l.type === 'add').length;
  const deletions = lines.filter((l) => l.type === 'delete').length;

  const copyDiff = () => {
    const text = lines.map((l) => `${l.type === 'add' ? '+' : l.type === 'delete' ? '-' : ' '} ${l.content}`).join('\n');
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  };

  return (
    <div
      className={cn(
        'rounded-2xl bg-white dark:bg-[#06070A] border border-zinc-200 dark:border-white/[0.06] overflow-hidden text-xs font-mono shadow-sm dark:shadow-lg',
        className
      )}
    >
      {/* Diff Header */}
      <div className="flex items-center justify-between px-4 py-2.5 bg-zinc-50 dark:bg-[#0B0C11] border-b border-zinc-200 dark:border-white/[0.04]">
        <div className="flex items-center gap-2">
          <GitCommit className="w-3.5 h-3.5 text-zinc-500 dark:text-zinc-400" />
          <span className="text-zinc-900 dark:text-zinc-200 font-medium">{fileName}</span>
          <div className="flex items-center gap-1.5 ml-2">
            <span className="text-emerald-600 dark:text-emerald-400 font-semibold">+{additions}</span>
            <span className="text-rose-600 dark:text-rose-400 font-semibold">-{deletions}</span>
          </div>
        </div>

        <button
          type="button"
          onClick={copyDiff}
          aria-label="Copy diff"
          className="p-1 rounded text-zinc-500 hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-white transition-colors cursor-pointer"
        >
          {copied ? <Check className="w-3.5 h-3.5 text-emerald-600 dark:text-emerald-400" /> : <Copy className="w-3.5 h-3.5" />}
        </button>
      </div>

      {/* Line Content */}
      <div className="divide-y divide-zinc-100 dark:divide-white/[0.02] overflow-x-auto py-1">
        {lines.map((line, idx) => {
          const isAdd = line.type === 'add';
          const isDelete = line.type === 'delete';

          return (
            <div
              key={idx}
              className={cn(
                'flex items-center px-2 py-0.5 leading-relaxed font-mono select-text',
                isAdd && 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-300 font-medium',
                isDelete && 'bg-rose-500/10 text-rose-700 dark:text-rose-300 line-through opacity-80',
                !isAdd && !isDelete && 'text-zinc-600 dark:text-zinc-400 hover:bg-zinc-50 dark:hover:bg-white/[0.02]'
              )}
            >
              {/* Line Numbers */}
              <div className="w-8 text-right pr-2 text-[10px] text-zinc-400 dark:text-zinc-600 select-none">
                {line.oldLineNumber || ''}
              </div>
              <div className="w-8 text-right pr-3 text-[10px] text-zinc-400 dark:text-zinc-600 select-none">
                {line.newLineNumber || ''}
              </div>

              {/* Sign */}
              <div className="w-4 select-none font-bold">
                {isAdd ? '+' : isDelete ? '-' : ' '}
              </div>

              {/* Code text */}
              <div className="flex-1 whitespace-pre">{line.content}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/**
 * UI99 — DonutRing (Wave D)
 * Zero-dependency SVG progress ring: single or multi-segment, center slot,
 * polished round caps, accessible via role="img" + aria-label.
 */

import React from 'react';
import { cn } from '../../lib/utils';

export interface DonutSegment {
  value: number;
  color?: 'emerald' | 'amber' | 'rose' | 'blue' | 'purple' | 'neutral';
}

const segColor = {
  emerald: '#10B981',
  amber: '#F59E0B',
  rose: '#F43F5E',
  blue: '#3B82F6',
  purple: '#A855F7',
  neutral: 'rgba(142,142,152,0.35)',
} as const;

export interface DonutRingProps {
  segments: DonutSegment[];
  size?: number;
  thickness?: number;
  label?: string;
  showValue?: boolean;
  valueSuffix?: string;
  className?: string;
  children?: React.ReactNode;
}

export function DonutRing({
  segments,
  size = 88,
  thickness = 8,
  label,
  showValue = false,
  valueSuffix = '%',
  className = '',
  children,
}: DonutRingProps) {
  const total = segments.reduce((s, seg) => s + seg.value, 0) || 1;
  const radius = (size - thickness) / 2;
  const circumference = 2 * Math.PI * radius;
  let offsetAcc = 0;

  return (
    <div className={cn('relative inline-flex items-center justify-center', className)} style={{ width: size, height: size }}>
      <svg
        role="img"
        aria-label={label ?? `Progress ring at ${Math.round((segments[0]?.value ?? 0) / total * 100)}%`}
        viewBox={`0 0 ${size} ${size}`}
        style={{ width: size, height: size }}
        className="-rotate-90"
      >
        {/* track */}
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke="rgba(142,142,152,0.15)"
          strokeWidth={thickness}
        />
        {segments.map((seg, i) => {
          const frac = seg.value / total;
          const dash = frac * circumference;
          const el = (
            <circle
              key={i}
              cx={size / 2}
              cy={size / 2}
              r={radius}
              fill="none"
              stroke={segColor[seg.color ?? 'emerald']}
              strokeWidth={thickness}
              strokeLinecap="round"
              strokeDasharray={`${Math.max(dash - 2, 0)} ${circumference - Math.max(dash - 2, 0)}`}
              strokeDashoffset={-offsetAcc}
              className="transition-all duration-300"
            />
          );
          offsetAcc += dash;
          return el;
        })}
      </svg>
      {(children || showValue) && (
        <div className="absolute inset-0 flex flex-col items-center justify-center">
          {children ?? (
            <span className="text-sm font-bold font-mono text-zinc-950 dark:text-white">
              {Math.round(((segments[0]?.value ?? 0) / total) * 100)}
              <span className="text-[10px] text-zinc-400">{valueSuffix}</span>
            </span>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * UI99 — Unified Velvet Dropdown / Select Component (Build 02.3)
 * Full WAI-ARIA listbox pattern: aria-haspopup="listbox", aria-activedescendant,
 * Arrow/Home/End/Type-ahead keyboard navigation, Escape dismissal with focus return,
 * focus trap while open, RTL-aware text alignment.
 * Dual-theme (Obsidian / Matte Porcelain) with tactile spring animations.
 */

import React, { useState, useRef, useEffect, ReactNode } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { ChevronDown, Check } from 'lucide-react';
import { useIsDark } from './theme';

export interface DropdownOption<T extends string = string> {
  value: T;
  label: string;
  icon?: ReactNode;
  description?: string;
  badge?: string;
}

export interface DropdownProps<T extends string = string> {
  options: DropdownOption<T>[];
  value: T;
  onChange: (value: T) => void;
  label?: string;
  placeholder?: string;
  className?: string;
  size?: 'sm' | 'md';
}

export function Dropdown<T extends string = string>({
  options,
  value,
  onChange,
  label,
  placeholder = 'Select an option',
  className = '',
  size = 'md',
}: DropdownProps<T>) {
  const isDark = useIsDark();
  const [isOpen, setIsOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const containerRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const typeAheadRef = useRef<{ chars: string; ts: number }>({ chars: '', ts: 0 });

  const selectedOption = options.find((o) => o.value === value);

  // Close on outside click
  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    }
    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [isOpen]);

  // Open → land focus/active on selected option; Close → restore focus to trigger
  useEffect(() => {
    if (isOpen) {
      const idx = options.findIndex((o) => o.value === value);
      setActiveIndex(idx >= 0 ? idx : 0);
    } else {
      triggerRef.current?.focus({ preventScroll: true });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen]);

  const commit = (index: number) => {
    const opt = options[index];
    if (!opt) return;
    onChange(opt.value);
    setIsOpen(false);
  };

  const handleTriggerKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      if (!isOpen) {
        setIsOpen(true);
        return;
      }
      if (e.key === 'ArrowDown') {
        setActiveIndex((i) => Math.min(options.length - 1, i + 1));
      } else if (e.key === 'ArrowUp') {
        setActiveIndex((i) => Math.max(0, i - 1));
      } else {
        commit(activeIndex);
      }
      return;
    }
    if (e.key === 'Escape') {
      if (isOpen) {
        e.preventDefault();
        setIsOpen(false);
      }
      return;
    }
    if (isOpen) typeAhead(e);
  };

  const typeAhead = (e: React.KeyboardEvent) => {
    if (!/^[a-zA-Z0-9\u0600-\u06FF]$/.test(e.key)) return;
    const now = Date.now();
    const chars = now - typeAheadRef.current.ts > 500 ? e.key : typeAheadRef.current.chars + e.key;
    typeAheadRef.current = { chars, ts: now };
    const needle = chars.toLowerCase();
    const idx = options.findIndex((o) => o.label.toLowerCase().startsWith(needle));
    if (idx >= 0) setActiveIndex(idx);
  };

  const sizeClass = size === 'sm' ? 'px-3 py-1.5 text-xs' : 'px-3.5 py-2 text-sm';
  const listId = `dropdown-list-${label || 'default'}`.replace(/\s+/g, '-').toLowerCase();

  return (
    <div className={`relative w-full ${className}`} ref={containerRef}>
      {label && (
        <span
          id={`${listId}-label`}
          className={`block text-xs font-semibold mb-1.5 ${
            isDark ? 'text-[#92929B]' : 'text-zinc-700'
          }`}
        >
          {label}
        </span>
      )}

      <button
        ref={triggerRef}
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        onKeyDown={handleTriggerKeyDown}
        className={`w-full flex items-center justify-between rounded-xl font-medium transition-all duration-150 cursor-pointer select-none focus-ui99 ${sizeClass} ${
          isDark
            ? 'bg-[#131317] text-[#EDEDEF] border border-white/[0.06] hover:border-white/[0.14] shadow-xs'
            : 'bg-white text-zinc-900 border border-black/[0.08] hover:border-black/[0.18] shadow-xs'
        }`}
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        aria-labelledby={label ? `${listId}-label` : undefined}
        aria-activedescendant={isOpen && activeIndex >= 0 ? `${listId}-opt-${activeIndex}` : undefined}
      >
        <span className="flex items-center gap-2 truncate">
          {selectedOption?.icon && <span className="shrink-0">{selectedOption.icon}</span>}
          <span className="truncate">{selectedOption ? selectedOption.label : placeholder}</span>
        </span>
        <ChevronDown
          className={`w-4 h-4 shrink-0 transition-transform duration-200 ${
            isOpen ? 'rotate-180' : ''
          } ${isDark ? 'text-zinc-400' : 'text-zinc-500'}`}
        />
      </button>

      <AnimatePresence>
        {isOpen && (
          <motion.ul
            id={listId}
            role="listbox"
            aria-labelledby={label ? `${listId}-label` : undefined}
            initial={{ opacity: 0, y: -4, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -4, scale: 0.98 }}
            transition={{ duration: 0.14 }}
            className={`absolute left-0 right-0 mt-1.5 p-1 rounded-2xl z-50 backdrop-blur-2xl shadow-xl overflow-hidden ${
              isDark
                ? 'bg-[#0E0E14]/95 border border-white/[0.07] shadow-[0_20px_40px_rgba(0,0,0,0.8)]'
                : 'bg-white/95 border border-black/[0.06] shadow-[0_16px_36px_rgba(0,0,0,0.08)]'
            }`}
          >
            <div className="max-h-60 overflow-y-auto no-scrollbar space-y-0.5">
              {options.map((option, index) => {
                const isSelected = option.value === value;
                const isActive = index === activeIndex;
                return (
                  <li
                    key={option.value}
                    id={`${listId}-opt-${index}`}
                    role="option"
                    aria-selected={isSelected}
                    onClick={() => commit(index)}
                    onMouseEnter={() => setActiveIndex(index)}
                    className={`w-full flex items-center justify-between px-3 py-2 rounded-xl text-xs sm:text-sm font-medium cursor-pointer text-left rtl:text-right focus-ui99-inset ${
                      isActive
                        ? isDark
                          ? 'bg-white/[0.08] text-white'
                          : 'bg-black/[0.05] text-zinc-950'
                        : isDark
                        ? 'text-zinc-300'
                        : 'text-zinc-700'
                    } ${isSelected ? 'font-semibold' : ''}`}
                  >
                    <div className="flex items-center gap-2 truncate pointer-events-none">
                      {option.icon && <span className="shrink-0">{option.icon}</span>}
                      <div className="truncate">
                        <div>{option.label}</div>
                        {option.description && (
                          <div
                            className={`text-[10px] ${
                              isDark ? 'text-zinc-500' : 'text-zinc-400'
                            }`}
                          >
                            {option.description}
                          </div>
                        )}
                      </div>
                    </div>
                    {isSelected && (
                      <Check className="w-3.5 h-3.5 text-emerald-500 shrink-0 ml-2 pointer-events-none" />
                    )}
                  </li>
                );
              })}
            </div>
          </motion.ul>
        )}
      </AnimatePresence>
    </div>
  );
