export interface DropdownButtonOption {
  value: string;
  label: string;
  icon?: React.ReactNode;
  disabled?: boolean;
}

export interface DropdownButtonProps {
  label: string;
  options: DropdownButtonOption[];
  onSelect: (value: string) => void;
  selected?: string;
  variant?: 'primary' | 'secondary' | 'outline';
  size?: 'sm' | 'md';
  disabled?: boolean;
  className?: string;
}

export function DropdownButton({
  label,
  options,
  onSelect,
  selected,
  variant = 'secondary',
  size = 'md',
  disabled = false,
  className = '',
}: DropdownButtonProps) {
  const [open, setOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    if (open) document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [open]);

  const sizeStyles = size === 'sm' ? 'h-8 px-2.5 text-xs' : 'h-9 px-3 text-xs';

  const variantStyles = {
    primary:
      'bg-zinc-900 dark:bg-white text-white dark:text-zinc-950 hover:bg-zinc-800 dark:hover:bg-zinc-100 border border-transparent shadow-xs',
    secondary:
      'bg-zinc-100 dark:bg-[#111218] text-zinc-900 dark:text-[#EDEDEF] hover:bg-zinc-200 dark:hover:bg-[#181924] border border-zinc-200/80 dark:border-white/[0.04]',
    outline:
      'bg-transparent text-zinc-900 dark:text-white hover:bg-zinc-100 dark:hover:bg-white/[0.04] border border-zinc-300 dark:border-white/[0.08]',
  }[variant];

  const currentLabel = options.find((o) => o.value === selected)?.label || label;

  return (
    <div ref={containerRef} className={`relative inline-block ${className}`}>
      <button
        type="button"
        disabled={disabled}
        onClick={() => setOpen(!open)}
        className={`rounded-xl font-medium inline-flex items-center gap-1.5 transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed ${sizeStyles} ${variantStyles}`}
      >
        <span>{currentLabel}</span>
        <ChevronDown className={`w-3.5 h-3.5 transition-transform ${open ? 'rotate-180' : ''}`} />
      </button>

      {open && (
        <div className="absolute top-full left-0 mt-1 min-w-[160px] py-1 rounded-xl bg-white dark:bg-[#0E0F16] border border-zinc-200 dark:border-white/[0.06] shadow-xl z-50 animate-in fade-in zoom-in-95 duration-100">
          {options.map((opt) => (
            <button
              key={opt.value}
              type="button"
              disabled={opt.disabled}
              onClick={() => {
                onSelect(opt.value);
                setOpen(false);
              }}
              className={`w-full px-3 py-1.5 text-xs text-left font-mono flex items-center justify-between transition-colors cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed ${
                selected === opt.value
                  ? 'bg-zinc-100 dark:bg-white/[0.08] text-emerald-500 font-bold'
                  : 'text-zinc-700 dark:text-zinc-300 hover:text-zinc-950 dark:hover:text-white hover:bg-zinc-100 dark:hover:bg-white/[0.04]'
              }`}
            >
              <div className="flex items-center gap-2">
                {opt.icon && <span className="w-3.5 h-3.5">{opt.icon}</span>}
                <span>{opt.label}</span>
              </div>
              {selected === opt.value && <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

