}

/**
 * UI99 — Rating (Wave H)
 * Interactive star rating with fractional display precision, keyboard
 * support (arrows/Home/End), velvet hover fill, minimum 28px targets.
  * @token Empty stars use 20–25% foreground; filled use the amber tint — both ≥3:1 against `--bg-card` (non-text UI, WCAG 1.4.11).
*/

import React, { useState } from 'react';
import { Star } from 'lucide-react';
import { cn } from '../../lib/utils';

export interface RatingProps {
  value: number;
  onChange?: (value: number) => void;
  max?: number;
  readOnly?: boolean;
  size?: 'sm' | 'md' | 'lg';
  className?: string;
}

export function Rating({ value, onChange, max = 5, readOnly = false, size = 'md', className = '' }: RatingProps) {
  const [hovered, setHovered] = useState<number | null>(null);
  const active = hovered ?? value;
  const sizes = { sm: 'w-4 h-4', md: 'w-5 h-5', lg: 'w-7 h-7' };
  const hitSizes = { sm: 'min-w-[28px]', md: 'min-w-[32px]', lg: 'min-w-[40px]' };

  return (
    <div
      className={cn('inline-flex items-center gap-0.5', className)}
      role={readOnly ? 'img' : 'radiogroup'}
      aria-label={`Rating: ${value} of ${max}`}
      onMouseLeave={() => setHovered(null)}
    >
      {Array.from({ length: max }).map((_, i) => {
        const starValue = i + 1;
        const filled = starValue <= active;
        return (
          <button
            key={i}
            type="button"
            role={readOnly ? undefined : 'radio'}
            aria-checked={readOnly ? undefined : starValue === value}
            aria-label={`${starValue} star${starValue > 1 ? 's' : ''}`}
            disabled={readOnly}
            onClick={() => onChange?.(starValue)}
            onMouseEnter={() => !readOnly && setHovered(starValue)}
            className={cn(
              'inline-flex items-center justify-center p-0.5 transition-transform',
              hitSizes[size],
              !readOnly && 'hover:scale-110 focus-visible:outline-none focus-ui99-inset cursor-pointer rounded-md',
              readOnly && 'cursor-default'
            )}
          >
            <Star
              className={cn(
                sizes[size],
                'transition-colors',
                filled
                  ? 'fill-amber-500 text-amber-500'
                  : 'fill-transparent text-black/[0.2] dark:text-white/[0.25]'
              )}
            />
          </button>
        );
      })}
    </div>
  );
}

/**
 * UI99 — RichTextEditorBar Component
 * Floating velvet toolbar for rich text editing with hotkey indicators.
 */

import React, { useState } from 'react';
import {
  Bold,
  Italic,
  Underline,
  Strikethrough,
  Code,
  Link,
  List,
  ListOrdered,
  Quote,
  AlignLeft,
  AlignCenter,
  AlignRight,
  Sparkles,
} from 'lucide-react';
import { cn } from '../../lib/utils';
import { Kbd } from './Kbd';

export interface RichTextEditorBarProps {
  onFormat?: (type: string) => void;
  className?: string;
  activeFormats?: string[];
}

export function RichTextEditorBar({
  onFormat,
  className,
  activeFormats = [],
}: RichTextEditorBarProps) {
  const [activeList, setActiveList] = useState<string[]>(activeFormats);

  const toggleFormat = (key: string) => {
    setActiveList((prev) =>
      prev.includes(key) ? prev.filter((k) => k !== key) : [...prev, key]
    );
    onFormat?.(key);
  };

  const buttons = [
    { key: 'bold', label: 'Bold', icon: Bold, shortcut: '⌘B' },
    { key: 'italic', label: 'Italic', icon: Italic, shortcut: '⌘I' },
    { key: 'underline', label: 'Underline', icon: Underline, shortcut: '⌘U' },
    { key: 'strikethrough', label: 'Strike', icon: Strikethrough },
    { type: 'separator' },
    { key: 'code', label: 'Code', icon: Code, shortcut: '⌘E' },
    { key: 'quote', label: 'Quote', icon: Quote },
    { type: 'separator' },
    { key: 'bullet', label: 'Bullet List', icon: List },
    { key: 'number', label: 'Numbered List', icon: ListOrdered },
    { type: 'separator' },
    { key: 'align-left', label: 'Left', icon: AlignLeft },
    { key: 'align-center', label: 'Center', icon: AlignCenter },
    { key: 'align-right', label: 'Right', icon: AlignRight },
  ];

  return (
    <div
      className={cn(
        'inline-flex items-center gap-0.5 p-1 rounded-2xl bg-white/95 dark:bg-[#0E0E14]/90 backdrop-blur-xl',
        'border border-black/[0.06] dark:border-white/[0.04] shadow-[0_12px_28px_-6px_rgba(0,0,0,0.45)]',
        className
      )}
    >
      {buttons.map((btn, idx) => {
        if (btn.type === 'separator') {
          return <div key={idx} className="w-[1px] h-4 bg-zinc-200 dark:bg-white/[0.06] mx-1" />;
        }
        const Icon = btn.icon!;
        const isActive = activeList.includes(btn.key!);

        return (
          <button
            key={btn.key}
            type="button"
            onClick={() => toggleFormat(btn.key!)}
            title={btn.label}
            className={cn(
              'p-1.5 rounded-lg transition-all text-zinc-500 hover:text-zinc-900 dark:hover:text-white',
              isActive
                ? 'bg-zinc-200 dark:bg-white/[0.1] text-zinc-900 dark:text-white shadow-xs font-semibold'
                : 'hover:bg-zinc-100 dark:hover:bg-white/[0.04]'
            )}
          >
            <Icon className="w-4 h-4" />
          </button>
        );
      })}
    </div>
  );
