/**
 * UI99 — Tactile Range Slider Component (Build 02.3)
 * Dual-theme (Obsidian Dark / Porcelain Light), smooth spring thumb, value readout.
 * RTL-aware: track fills and thumb position mirror under [dir="rtl"].
 * The native <input type="range"> is the accessibility root (keyboard + AT),
 * with aria-valuetext exposing the unit.
 */

import React from 'react';
import { useIsDark } from './theme';

export interface SliderProps {
  value: number;
  onChange: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  label?: string;
  unit?: string;
  disabled?: boolean;
  className?: string;
}

export function Slider({
  value,
  onChange,
  min = 0,
  max = 100,
  step = 1,
  label,
  unit = '%',
  disabled = false,
  className = '',
}: SliderProps) {
  const isDark = useIsDark();

  const percentage = Math.min(100, Math.max(0, ((value - min) / (max - min)) * 100));

  return (
    <div
      className={`w-full space-y-2 select-none ${disabled ? 'opacity-40 pointer-events-none' : ''} ${className}`}
    >
      {(label || unit) && (
        <div className="flex items-center justify-between text-xs">
          {label && (
            <span className={`font-semibold tracking-tight ${isDark ? 'text-[#EDEDEF]' : 'text-zinc-800'}`}>
              {label}
            </span>
          )}
          <span className="font-mono text-zinc-500 text-[11px]">
            {value}
            {unit}
          </span>
        </div>
      )}

      {/* RTL mirroring: container is dir-neutral; [dir=rtl] fills from the right */}
      <div className="relative flex items-center h-5 slider-ui99" dir="ltr">
        {/* Track background */}
        <div
          className={`w-full h-1.5 rounded-full overflow-hidden ${
            isDark ? 'bg-white/[0.08]' : 'bg-black/[0.08]'
          }`}
        >
          {/* Active filled track */}
          <div
            className="h-full bg-emerald-500 rounded-full transition-all duration-75 shadow-[0_0_8px_rgba(16,185,129,0.35)] slider-fill"
            style={{ width: `${percentage}%` }}
          />
        </div>

        {/* Real hidden range input overlaid for native accessibility & keyboard support */}
        <input
          type="range"
          aria-label={label}
          aria-valuetext={`${value}${unit}`}
          min={min}
          max={max}
          step={step}
          value={value}
          disabled={disabled}
          onChange={(e) => onChange(Number(e.target.value))}
          className="absolute inset-0 w-full h-full opacity-0 cursor-pointer focus-visible:ring-2 focus-visible:ring-emerald-500/55 rounded-full"
        />

        {/* Visual tactile thumb */}
        <div
          className={`absolute pointer-events-none w-4 h-4 rounded-full -translate-x-1/2 shadow-md transition-transform duration-75 slider-thumb ${
            isDark
              ? 'bg-white border-2 border-[#131318] shadow-[0_2px_8px_rgba(0,0,0,0.5)]'
              : 'bg-white border-2 border-emerald-500 shadow-[0_2px_8px_rgba(0,0,0,0.15)]'
          }`}
          style={{ left: `${percentage}%`, ['--thumb-pos' as string]: `${100 - percentage}%` }}
        />
      </div>
    </div>
  );
}

/**
 * UI99 — Sparkline (Wave D)
 * Zero-dependency SVG micro-chart: line or bar mode, gradient fill option,
 * a11y via role="img" + aria-label. No chart library — 2KB of math.
 */

import React, { useId } from 'react';
import { cn } from '../../lib/utils';

export interface SparklineProps {
  data: number[];
  mode?: 'line' | 'bar';
  width?: number;
  height?: number;
  color?: 'emerald' | 'amber' | 'rose' | 'blue' | 'purple' | 'neutral';
  fill?: boolean;
  strokeWidth?: number;
  label?: string;
  className?: string;
}

const colorMap = {
  emerald: '#10B981',
  amber: '#F59E0B',
  rose: '#F43F5E',
  blue: '#3B82F6',
  purple: '#A855F7',
  neutral: '#8E8E98',
} as const;

export function Sparkline({
  data,
  mode = 'line',
  width = 120,
  height = 36,
  color = 'emerald',
  fill = true,
  strokeWidth = 1.5,
  label,
  className = '',
}: SparklineProps) {
  const gradId = useId();
  const hex = colorMap[color];

  if (data.length === 0) return null;
  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;

  if (mode === 'bar') {
    const gap = 1.5;
    const barW = Math.max((width - gap * (data.length - 1)) / data.length, 1);
    return (
      <svg
        role="img"
        aria-label={label ?? `Bar sparkline, ${data.length} points`}
        viewBox={`0 0 ${width} ${height}`}
        className={cn('overflow-visible', className)}
        style={{ width, height }}
      >
        {data.map((v, i) => {
          const h = Math.max(((v - min) / range) * (height - 2), 1);
          return (
            <rect
              key={i}
              x={i * (barW + gap)}
              y={height - h}
              width={barW}
              height={h}
              rx={Math.min(barW / 2, 2)}
              fill={hex}
              opacity={0.35 + 0.65 * (v / max)}
            />
          );
        })}
      </svg>
    );
  }

  const step = width / Math.max(data.length - 1, 1);
  const points = data.map((v, i) => [i * step, height - 2 - ((v - min) / range) * (height - 4)] as const);
  const line = points.map(([x, y], i) => `${i === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
  const area = `${line} L${width},${height} L0,${height} Z`;

  return (
    <svg
      role="img"
      aria-label={label ?? `Line sparkline, ${data.length} points`}
      viewBox={`0 0 ${width} ${height}`}
      className={cn('overflow-visible', className)}
      style={{ width, height }}
    >
      {fill && (
        <>
          <defs>
            <linearGradient id={gradId} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={hex} stopOpacity="0.25" />
              <stop offset="100%" stopColor={hex} stopOpacity="0" />
            </linearGradient>
          </defs>
          <path d={area} fill={`url(#${gradId})`} />
        </>
      )}
      <path
        d={line}
        fill="none"
        stroke={hex}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <circle cx={points[points.length - 1][0]} cy={points[points.length - 1][1]} r={2.2} fill={hex} />
    </svg>
  );
}

