/**
 * UI \ [99] — SplitButton Primitive
 * Primary action combined with a chevron dropdown trigger.
 */

import React, { useState, useRef, useEffect } from 'react';
import { ChevronDown } from 'lucide-react';

export interface SplitButtonItem {
  label: string;
  onClick: () => void;
  icon?: React.ReactNode;
  disabled?: boolean;
}

export interface SplitButtonProps {
  label: string;
  onClick: () => void;
  items: SplitButtonItem[];
  variant?: 'primary' | 'secondary' | 'outline';
  size?: 'sm' | 'md' | 'lg';
  disabled?: boolean;
  className?: string;
}

export function SplitButton({
  label,
  onClick,
  items,
  variant = 'primary',
  size = 'md',
  disabled = false,
  className = '',
}: SplitButtonProps) {
  const [open, setOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    if (open) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [open]);

  const sizeClasses = {
    sm: 'h-8 text-xs',
    md: 'h-9 text-xs',
    lg: 'h-10 text-sm',
  }[size];

  const mainPadding = {
    sm: 'px-3',
    md: 'px-3.5',
    lg: 'px-4',
  }[size];

  const triggerPadding = {
    sm: 'px-2',
    md: 'px-2.5',
    lg: 'px-3',
  }[size];

  const variantStyles = {
    primary:
      'bg-zinc-900 dark:bg-white text-white dark:text-zinc-950 hover:bg-zinc-800 dark:hover:bg-zinc-100 border border-transparent shadow-xs',
    secondary:
      'bg-zinc-100 dark:bg-[#111218] text-zinc-900 dark:text-[#EDEDEF] hover:bg-zinc-200 dark:hover:bg-[#171822] border border-zinc-200/80 dark:border-white/[0.04]',
    outline:
      'bg-transparent text-zinc-900 dark:text-white hover:bg-zinc-100 dark:hover:bg-white/[0.04] border border-zinc-300 dark:border-white/[0.08]',
  }[variant];

  return (
    <div ref={containerRef} className={`relative inline-flex items-stretch rounded-xl shadow-xs ${className}`}>
      {/* Primary Action */}
      <button
        type="button"
        disabled={disabled}
        onClick={onClick}
        className={`${sizeClasses} ${mainPadding} ${variantStyles} rounded-l-xl font-medium flex items-center justify-center transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed active:scale-[0.98]`}
      >
        {label}
      </button>

      {/* Divider */}
      <div
        className={`w-px ${
          variant === 'primary'
            ? 'bg-zinc-700 dark:bg-zinc-300'
            : 'bg-zinc-300 dark:bg-white/[0.08]'
        }`}
      />

      {/* Menu Trigger */}
      <button
        type="button"
        disabled={disabled}
        onClick={() => setOpen(!open)}
        aria-haspopup="menu"
        aria-expanded={open}
        className={`${sizeClasses} ${triggerPadding} ${variantStyles} rounded-r-xl flex items-center justify-center transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed`}
      >
        <ChevronDown className={`w-3.5 h-3.5 transition-transform ${open ? 'rotate-180' : ''}`} />
      </button>

      {/* Dropdown Menu */}
      {open && (
        <div className="absolute top-full right-0 mt-1.5 min-w-[160px] py-1 rounded-xl bg-white dark:bg-[#0E0F16] border border-zinc-200 dark:border-white/[0.06] shadow-xl z-50 animate-in fade-in zoom-in-95 duration-100">
          {items.map((item, idx) => (
            <button
              key={idx}
              type="button"
              disabled={item.disabled}
              onClick={() => {
                item.onClick();
                setOpen(false);
              }}
              className="w-full px-3 py-1.5 text-xs text-left font-mono flex items-center gap-2 text-zinc-700 dark:text-zinc-300 hover:text-zinc-950 dark:hover:text-white hover:bg-zinc-100 dark:hover:bg-white/[0.06] transition-colors cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed"
            >
              {item.icon && <span className="w-3.5 h-3.5">{item.icon}</span>}
              <span>{item.label}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/**
 * UI99 — StatTile (Wave D)
 * Metric card: value, label, delta chip (up/down/flat), optional trailing
 * sparkline slot. The workhorse of dashboards.
 */

import React from 'react';
import { ArrowUpRight, ArrowDownRight, Minus } from 'lucide-react';
import { cn } from '../../lib/utils';

export interface StatTileProps {
  label: string;
  value: string | number;
  delta?: number;
  deltaSuffix?: string;
  trend?: React.ReactNode;
  size?: 'sm' | 'md' | 'lg';
  className?: string;
}

export function StatTile({
  label,
  value,
  delta,
  deltaSuffix = '%',
  trend,
  size = 'md',
  className = '',
}: StatTileProps) {
  const deltaTone =
    delta === undefined ? 'neutral' : delta > 0 ? 'up' : delta < 0 ? 'down' : 'flat';
  const toneStyle = {
    up: 'text-emerald-600 dark:text-emerald-400',
    down: 'text-rose-600 dark:text-rose-400',
    flat: 'text-(--text-secondary)',
    neutral: '',
  }[deltaTone];
  const DeltaIcon =
    deltaTone === 'up' ? ArrowUpRight : deltaTone === 'down' ? ArrowDownRight : Minus;

  const valueSize = {
    sm: 'text-lg',
    md: 'text-2xl',
    lg: 'text-3xl sm:text-4xl',
  }[size];

  return (
    <div
      className={cn(
        'rounded-2xl bg-(--bg-card) border border-(--border-hairline) p-4 sm:p-5',
        'shadow-[0_4px_16px_rgba(0,0,0,0.03)] dark:shadow-[inset_0_1px_0_0_rgba(255,255,255,0.04),0_8px_24px_-4px_rgba(0,0,0,0.5)]',
        'space-y-1.5',
        className
      )}
    >
      <div className="flex items-center justify-between gap-2">
        <span className="text-[11px] font-mono uppercase tracking-wider text-(--text-secondary)">
          {label}
        </span>
        {trend && <span className="shrink-0">{trend}</span>}
      </div>
      <div className={cn('font-bold font-mono tracking-tight text-zinc-950 dark:text-white', valueSize)}>
        {value}
      </div>
      {delta !== undefined && (
        <div className={cn('flex items-center gap-1 text-[11px] font-mono font-semibold', toneStyle)}>
          <DeltaIcon className="w-3 h-3" />
          {delta > 0 ? '+' : ''}
          {delta}
          {deltaSuffix}
          <span className="text-(--text-muted) font-normal">vs last week</span>
        </div>
      )}
    </div>
  );
}

/**
 * UI99 — Stepper (Wave C)
 * Multi-step progress indicator (Linear/Onboarding pattern): completed /
 * current / upcoming states, connector hairlines, aria-current="step".
 */

import React from 'react';
import { Check } from 'lucide-react';
import { cn } from '../../lib/utils';

export interface StepperProps extends React.ComponentProps<'ol'> {
  steps: string[];
  current: number;
  orientation?: 'horizontal' | 'vertical';
}

export function Stepper({
  steps,
  current,
  orientation = 'horizontal',
  className = '',
  ...props
}: StepperProps) {
  return (
    <ol
      className={cn(
        'flex gap-0',
        orientation === 'horizontal' ? 'flex-row items-center' : 'flex-col',
        className
      )}
      {...props}
    >
      {steps.map((step, i) => {
        const isDone = i < current;
        const isCurrent = i === current;
        return (
          <li
            key={step}
            aria-current={isCurrent ? 'step' : undefined}
            className={cn(
              'flex items-center',
              orientation === 'horizontal' ? 'flex-1 last:flex-none' : 'gap-3 pb-4 last:pb-0'
            )}
          >
            <span
              className={cn(
                'flex h-7 w-7 shrink-0 items-center justify-center rounded-full border text-[11px] font-mono font-bold transition-all duration-200',
                isDone &&
                  'bg-emerald-500 text-white border-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.35)]',
                isCurrent &&
                  'bg-zinc-900 text-white border-zinc-900 dark:bg-[#EBEBEF] dark:text-[#0C0C0E] dark:border-[#EBEBEF] ring-4 ring-black/[0.04] dark:ring-white/[0.06]',
                !isDone && !isCurrent &&
                  'bg-transparent text-zinc-400 border-(--border-strong)'
              )}
            >
              {isDone ? <Check className="w-3.5 h-3.5" /> : i + 1}
            </span>
            <span
              className={cn(
                'text-xs font-medium tracking-tight',
                orientation === 'horizontal' ? 'ml-2 hidden sm:block' : '',
                isCurrent
                  ? 'text-zinc-950 dark:text-white font-semibold'
                  : 'text-(--text-secondary)'
              )}
            >
              {step}
            </span>
            {orientation === 'horizontal' && i < steps.length - 1 && (
              <span
                aria-hidden="true"
                className={cn(
                  'mx-3 h-px flex-1 transition-colors duration-200',
                  i < current ? 'bg-emerald-500/50' : 'bg-black/[0.08] dark:bg-white/[0.08]'
                )}
              />
            )}
          </li>
        );
      })}
    </ol>
  );
}

/**
 * UI99 — Swatch (Wave H)
 * Design-token presentation chip: literal hex display + copy affordance.
 * The color-science layer of the docs — every palette token shown exactly.
  * @token Chip label bar resolves `--bg-card`; hex text is computed against the swatch itself for guaranteed ≥4.5:1.
*/

import React from 'react';
import { cn } from '../../lib/utils';
import { CopyButton } from './CopyButton';

export interface SwatchProps {
  name: string;
  hex: string;
  contrastNote?: string;
  className?: string;
}

export function Swatch({ name, hex, contrastNote, className = '' }: SwatchProps) {
  // Pick readable foreground against the swatch itself.
  const r = parseInt(hex.slice(1, 3), 16) / 255;
  const g = parseInt(hex.slice(3, 5), 16) / 255;
  const b = parseInt(hex.slice(5, 7), 16) / 255;
  const lum = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  const light = lum > 0.4;

  return (
    <div
      className={cn(
        'group overflow-hidden rounded-2xl border border-black/[0.05] dark:border-white/[0.04]',
        className
      )}
    >
      <div className="flex h-16 items-end justify-between p-2.5" style={{ background: hex }}>
        <span
          className={cn('font-mono text-[10px] font-semibold', light ? 'text-black/70' : 'text-white/80')}
        >
          {hex}
        </span>
        <CopyButton text={hex} label="" size="sm" className={cn('opacity-0 group-hover:opacity-100 transition-opacity', light ? 'border-black/[0.12]' : 'border-white/[0.12]')} />
      </div>
      <div className="bg-white px-3 py-2.5 dark:bg-[#0B0C11]">
        <div className="text-xs font-semibold text-(--text-primary)">{name}</div>
        {contrastNote && (
          <div className="mt-0.5 text-[10px] font-mono text-(--text-muted)">{contrastNote}</div>
        )}
      </div>
    </div>
  );
}

/**
 * UI99 — Tactile Switch / Toggle Component (Build 02.2)
 * Dual-theme (Obsidian / Matte Porcelain) with Radix UI headless accessibility and tactile spring.
 *
 * @token Track off-state rides `--state-selected` over `--bg-sunken`; on-state
 *   fills the success token. Thumb shadow is the soft-contact profile
 *   (0 2px 6px rgba(0,0,0,0.25)) — never a hard border.
 */

import React from 'react';
import * as SwitchPrimitive from '@radix-ui/react-switch';
import { cn } from '../../lib/utils';
import { useIsDark } from './theme';

export interface SwitchProps {
  checked: boolean;
  onChange?: (checked: boolean) => void;
  onCheckedChange?: (checked: boolean) => void;
  label?: string;
  description?: string;
  disabled?: boolean;
  size?: 'sm' | 'md' | 'lg';
  className?: string;
}

export function Switch({
  checked,
  onChange,
  onCheckedChange,
  label,
  description,
  disabled = false,
  size = 'md',
  className = '',
}: SwitchProps) {
  const isDark = useIsDark();

  const handleChange = (val: boolean) => {
    onChange?.(val);
    onCheckedChange?.(val);
  };

  const rootSizes = {
    sm: 'h-5 w-9',
    md: 'h-6 w-11',
    lg: 'h-7 w-12',
  }[size];

  const thumbSizes = {
    sm: 'h-4 w-4 data-[state=checked]:translate-x-4 data-[state=unchecked]:translate-x-0.5 rtl:data-[state=checked]:-translate-x-4 rtl:data-[state=unchecked]:-translate-x-0.5',
    md: 'h-5 w-5 data-[state=checked]:translate-x-5 data-[state=unchecked]:translate-x-0.5 rtl:data-[state=checked]:-translate-x-5 rtl:data-[state=unchecked]:-translate-x-0.5',
    lg: 'h-5 w-5 data-[state=checked]:translate-x-6 data-[state=unchecked]:translate-x-1 rtl:data-[state=checked]:-translate-x-6 rtl:data-[state=unchecked]:-translate-x-1',
  }[size];

  return (
    <label
      className={cn(
        'inline-flex items-center gap-3 cursor-pointer select-none',
        disabled && 'opacity-40 cursor-not-allowed pointer-events-none',
        className
      )}
    >
      <SwitchPrimitive.Root
        checked={checked}
        onCheckedChange={handleChange}
        disabled={disabled}
        className={cn(
          'peer inline-flex shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent transition-colors focus-visible:outline-none focus-ui99 disabled:cursor-not-allowed',
          rootSizes,
          checked
            ? 'bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.35)]'
            : isDark
            ? 'bg-[#181820] border-white/[0.08]'
            : 'bg-zinc-200 border-black/[0.06]'
        )}
      >
        <SwitchPrimitive.Thumb
          className={cn(
            'pointer-events-none block rounded-full bg-white shadow-md ring-0 transition-transform duration-200 ease-in-out',
            thumbSizes
          )}
        />
      </SwitchPrimitive.Root>

      {(label || description) && (
        <div className="flex flex-col text-left rtl:text-right">
          {label && (
            <span
              className={cn(
                'text-xs font-semibold tracking-tight',
                isDark ? 'text-[#EDEDEF]' : 'text-zinc-900'
              )}
            >
              {label}
            </span>
          )}
          {description && (
            <span
              className={cn(
                'text-[11px] leading-tight',
                isDark ? 'text-[#8E8E98]' : 'text-zinc-500'
              )}
            >
              {description}
            </span>
          )}
        </div>
      )}
    </label>
  );
}

