/**
 * UI99 — TagInput Component
 * Multi-tag tokenized chip input with keyboard navigation, backspace deletion, and autocomplete.
 */

import React, { useState, useRef, KeyboardEvent } from 'react';
import { X, Tag as TagIcon, Plus } from 'lucide-react';
import { cn } from '../../lib/utils';

export interface TagInputProps {
  tags: string[];
  onChange: (tags: string[]) => void;
  suggestions?: string[];
  placeholder?: string;
  maxTags?: number;
  className?: string;
  label?: string;
}

export function TagInput({
  tags = [],
  onChange,
  suggestions = ['TypeScript', 'Tailwind', 'React', 'Motion', 'Obsidian', 'DesignSystem', 'Linear'],
  placeholder = 'Add tag and press Enter...',
  maxTags = 12,
  className,
  label,
}: TagInputProps) {
  const [inputVal, setInputVal] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const inputRef = useRef<HTMLInputElement | null>(null);

  const filteredSuggestions = suggestions.filter(
    (s) =>
      s.toLowerCase().includes(inputVal.toLowerCase()) &&
      !tags.some((t) => t.toLowerCase() === s.toLowerCase())
  );

  const addTag = (tagToAdd: string) => {
    const trimmed = tagToAdd.trim();
    if (!trimmed) return;
    if (tags.length >= maxTags) return;
    if (tags.some((t) => t.toLowerCase() === trimmed.toLowerCase())) return;

    onChange([...tags, trimmed]);
    setInputVal('');
    setShowSuggestions(false);
  };

  const removeTag = (indexToRemove: number) => {
    onChange(tags.filter((_, idx) => idx !== indexToRemove));
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' || e.key === ',') {
      e.preventDefault();
      addTag(inputVal);
    } else if (e.key === 'Backspace' && !inputVal && tags.length > 0) {
      removeTag(tags.length - 1);
    }
  };

  return (
    <div className="flex flex-col gap-1.5 w-full relative">
      {label && <label className="text-xs font-medium text-zinc-700 dark:text-zinc-300">{label}</label>}

      <div
        onClick={() => inputRef.current?.focus()}
        className={cn(
          'flex flex-wrap items-center gap-1.5 p-2 min-h-[42px] rounded-xl transition-all duration-150 cursor-text',
          'bg-zinc-50 dark:bg-[#0B0C11] text-zinc-900 dark:text-[#EDEDEF]',
          'border border-black/[0.08] dark:border-white/[0.06] focus-within:border-zinc-500 dark:focus-within:border-white/20',
          className
        )}
      >
        {tags.map((tag, idx) => (
          <span
            key={tag + idx}
            className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-medium bg-zinc-200/80 dark:bg-white/[0.06] text-zinc-800 dark:text-zinc-200 border border-black/[0.04] dark:border-white/[0.04] animate-in fade-in zoom-in-95"
          >
            <TagIcon className="w-3 h-3 text-zinc-400 shrink-0" />
            <span>{tag}</span>
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation();
                removeTag(idx);
              }}
              className="p-0.5 hover:bg-black/10 dark:hover:bg-white/10 rounded-full transition-colors text-zinc-400 hover:text-zinc-700 dark:hover:text-zinc-200"
            >
              <X className="w-3 h-3" />
            </button>
          </span>
        ))}

        {tags.length < maxTags && (
          <input
            ref={inputRef}
            type="text"
            value={inputVal}
            onChange={(e) => {
              setInputVal(e.target.value);
              setShowSuggestions(true);
            }}
            onFocus={() => setShowSuggestions(true)}
            onBlur={() => setTimeout(() => setShowSuggestions(false), 200)}
            onKeyDown={handleKeyDown}
            placeholder={tags.length === 0 ? placeholder : ''}
            className="flex-1 min-w-[120px] bg-transparent text-sm text-zinc-900 dark:text-zinc-100 placeholder-zinc-400 outline-none py-0.5"
          />
        )}
      </div>

      {/* Autocomplete Dropdown */}
      {showSuggestions && inputVal && filteredSuggestions.length > 0 && (
        <div className="absolute top-full left-0 right-0 mt-1 z-30 p-1 rounded-xl bg-white dark:bg-[#131318] border border-black/10 dark:border-white/10 shadow-xl max-h-40 overflow-y-auto">
          {filteredSuggestions.map((s) => (
            <button
              key={s}
              type="button"
              onMouseDown={() => addTag(s)}
              className="w-full text-left px-3 py-1.5 text-xs rounded-lg hover:bg-zinc-100 dark:hover:bg-white/[0.05] text-zinc-800 dark:text-zinc-200 flex items-center justify-between transition-colors"
            >
              <span>{s}</span>
              <Plus className="w-3 h-3 text-zinc-400" />
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/**
 * UI99 — TerminalEmulator Component
 * Interactive Obsidian terminal CLI runner with command history, status badges, and syntax highlighting.
 */

import React, { useState, useRef, useEffect } from 'react';
import { Terminal, Play, Copy, Check, Trash2, CornerDownLeft } from 'lucide-react';
import { cn } from '../../lib/utils';
import { Kbd } from './Kbd';

export interface TerminalLog {
  id: string;
  command: string;
  output?: string;
  status: 'success' | 'error' | 'pending';
  timestamp: string;
}

export interface TerminalEmulatorProps {
  initialLogs?: TerminalLog[];
  onExecute?: (command: string) => Promise<string | void>;
  className?: string;
}

const DEFAULT_LOGS: TerminalLog[] = [
  {
    id: '1',
    command: 'npx @99/ui add button badge card switch tabs',
    output: '✔ Installed 5 components\n✔ Validated WCAG AAA contrast ratio\n✔ Generated tailwind specular tokens',
    status: 'success',
    timestamp: '10:42:01',
  },
  {
    id: '2',
    command: 'ui99 audit --strict',
    output: 'Obsidian Velvet Tokens: 100% OK\nMathematical Radii Nesting: PASS (Inner = Outer - P)\nSlop Ratio: 0.00%',
    status: 'success',
    timestamp: '10:42:15',
  },
];

export function TerminalEmulator({
  initialLogs = DEFAULT_LOGS,
  onExecute,
  className,
}: TerminalEmulatorProps) {
  const [logs, setLogs] = useState<TerminalLog[]>(initialLogs);
  const [inputVal, setInputVal] = useState('');
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);
  const containerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [logs]);

  const runCommand = async (e: React.FormEvent) => {
    e.preventDefault();
    const cmd = inputVal.trim();
    if (!cmd || loading) return;

    const newId = Date.now().toString();
    const time = new Date().toTimeString().split(' ')[0];

    if (cmd === 'clear') {
      setLogs([]);
      setInputVal('');
      return;
    }

    setLoading(true);
    setInputVal('');

    setLogs((prev) => [
      ...prev,
      { id: newId, command: cmd, status: 'pending', timestamp: time },
    ]);

    try {
      let result = 'Command executed successfully.';
      if (onExecute) {
        const res = await onExecute(cmd);
        if (res) result = res;
      } else {
        if (cmd.startsWith('add') || cmd.startsWith('npx')) {
          result = `✔ Added component to src/components/ui/`;
        } else if (cmd === 'help') {
          result = `Available commands: add <component>, audit, clear, status, info`;
        } else {
          result = `Executed: ${cmd}`;
        }
      }

      setLogs((prev) =>
        prev.map((l) =>
          l.id === newId ? { ...l, output: result, status: 'success' } : l
        )
      );
    } catch (err: any) {
      setLogs((prev) =>
        prev.map((l) =>
          l.id === newId ? { ...l, output: err?.message || 'Error executing command', status: 'error' } : l
        )
      );
    } finally {
      setLoading(false);
    }
  };

  const copyAll = () => {
    const text = logs.map((l) => `$ ${l.command}\n${l.output || ''}`).join('\n\n');
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  };

  return (
    <div
      className={cn(
        'rounded-2xl bg-[#06070A] border border-white/[0.06] text-xs font-mono flex flex-col shadow-xl overflow-hidden w-full',
        className
      )}
    >
      {/* Top Titlebar */}
      <div className="flex items-center justify-between px-3.5 py-2.5 bg-[#0B0C11] border-b border-white/[0.04]">
        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1.5">
            <div className="w-2.5 h-2.5 rounded-full bg-rose-500/80" />
            <div className="w-2.5 h-2.5 rounded-full bg-amber-500/80" />
            <div className="w-2.5 h-2.5 rounded-full bg-emerald-500/80" />
          </div>
          <span className="text-zinc-400 font-medium ml-2 flex items-center gap-1.5">
            <Terminal className="w-3.5 h-3.5 text-zinc-400" />
            ui99-cli ~ v1.0.0
          </span>
        </div>

        <div className="flex items-center gap-1.5">
          <button
            type="button"
            onClick={copyAll}
            className="p-1 rounded text-zinc-400 hover:text-white transition-colors"
            title="Copy terminal session"
          >
            {copied ? <Check className="w-3.5 h-3.5 text-emerald-400" /> : <Copy className="w-3.5 h-3.5" />}
          </button>
          <button
            type="button"
            onClick={() => setLogs([])}
            className="p-1 rounded text-zinc-400 hover:text-rose-400 transition-colors"
            title="Clear"
          >
            <Trash2 className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>

      {/* Log Output */}
      <div
        ref={containerRef}
        className="p-4 flex flex-col gap-3 min-h-[160px] max-h-[280px] overflow-y-auto divide-y divide-white/[0.02]"
      >
        {logs.map((log) => (
          <div key={log.id} className="pt-2 first:pt-0 flex flex-col gap-1">
            <div className="flex items-center gap-2 text-zinc-200 font-semibold">
              <span className="text-emerald-400 font-bold">$</span>
              <span>{log.command}</span>
              <span className="text-[10px] text-zinc-600 ml-auto">{log.timestamp}</span>
            </div>

            {log.output && (
              <pre className={cn(
                'whitespace-pre-wrap pl-4 text-xs font-mono',
                log.status === 'error' ? 'text-rose-400' : 'text-zinc-400'
              )}>
                {log.output}
              </pre>
            )}
          </div>
        ))}
      </div>

      {/* Command Input Form */}
      <form
        onSubmit={runCommand}
        className="flex items-center gap-2 px-3.5 py-2.5 bg-[#0B0C11] border-t border-white/[0.04]"
      >
        <span className="text-emerald-400 font-bold">$</span>
        <input
          type="text"
          value={inputVal}
          onChange={(e) => setInputVal(e.target.value)}
          placeholder="Try 'add button' or 'help'..."
          className="flex-1 bg-transparent text-zinc-100 placeholder-zinc-600 outline-none text-xs font-mono"
        />
        <button
          type="submit"
          disabled={!inputVal.trim() || loading}
          className="p-1 rounded text-zinc-400 hover:text-white disabled:opacity-30 transition-colors"
        >
          <CornerDownLeft className="w-3.5 h-3.5" />
        </button>
      </form>
    </div>
  );
}

/**
 * UI99 — TimePicker (Wave F)
 * Filterable 24h time listbox at a configurable step. Velvet rows with
 * selected inversion, keyboard focusable options, `HH:mm` contract.
  * @token Rows invert on selection (`--text-on-fill`); filter input focus rides `--focus-ring` via `focus-ui99-inset`.
*/

import React, { useState, useMemo } from 'react';
import { cn } from '../../lib/utils';

export interface TimePickerProps {
  /** 24h `HH:mm` string or null. */
  value: string | null;
  onChange: (value: string | null) => void;
  /** Slot resolution in minutes (must divide 60). */
  step?: 5 | 10 | 15 | 30 | 60;
  className?: string;
}

export function TimePicker({ value, onChange, step = 30, className = '' }: TimePickerProps) {
  const [query, setQuery] = useState('');

  const slots = useMemo(() => {
    const out: string[] = [];
    for (let h = 0; h < 24; h++) {
      for (let m = 0; m < 60; m += step) {
        out.push(`${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`);
      }
    }
    return out;
  }, [step]);

  const filtered = useMemo(() => slots.filter((t) => t.includes(query)), [slots, query]);

  return (
    <div className={cn('rounded-2xl border border-black/[0.06] bg-white p-3 dark:border-white/[0.06] dark:bg-[#131318]', className)}>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Filter times…"
        aria-label="Filter times"
        className={cn(
          'mb-2 h-9 w-full rounded-xl border border-black/[0.07] bg-transparent px-3 text-sm text-zinc-950 placeholder:text-zinc-400',
          'dark:border-white/[0.07] dark:text-[#EDEDEF] dark:placeholder:text-[#71717A]',
          'focus-visible:outline-none focus-ui99-inset'
        )}
      />
      <div role="listbox" aria-label="Time" className="no-scrollbar max-h-48 overflow-y-auto">
        {filtered.map((t) => (
          <button
            key={t}
            type="button"
            role="option"
            aria-selected={t === value}
            onClick={() => onChange(t)}
            className={cn(
              'flex min-h-[36px] w-full items-center justify-between rounded-lg px-3 text-left text-xs font-mono transition-colors',
              'hover:bg-(--state-hover)',
              'focus-visible:outline-none focus-ui99-inset cursor-pointer',
              t === value
                ? 'bg-zinc-950 text-white dark:bg-white dark:text-zinc-950'
                : 'text-(--text-primary)'
            )}
          >
            {t}
          </button>
        ))}
        {filtered.length === 0 && (
          <div className="px-3 py-4 text-center text-xs text-(--text-muted)">No match</div>
        )}
      </div>
    </div>
  );
}

