/**
 * UI99 — TourGuide Component
 * Interactive product walkthrough and onboarding spotlight card with step pagination.
 */

import React, { useState } from 'react';
import { Sparkles, ChevronRight, ChevronLeft, X, Check } from 'lucide-react';
import { cn } from '../../lib/utils';
import { Button } from './Button';

export interface TourStep {
  title: string;
  description: string;
  badge?: string;
}

export interface TourGuideProps {
  steps: TourStep[];
  onComplete?: () => void;
  onDismiss?: () => void;
  className?: string;
}

export function TourGuide({
  steps,
  onComplete,
  onDismiss,
  className,
}: TourGuideProps) {
  const [currentStep, setCurrentStep] = useState(0);

  const step = steps[currentStep];
  const isLast = currentStep === steps.length - 1;

  const next = () => {
    if (isLast) {
      onComplete?.();
    } else {
      setCurrentStep((prev) => prev + 1);
    }
  };

  const prev = () => {
    setCurrentStep((prev) => Math.max(0, prev - 1));
  };

  if (!step) return null;

  return (
    <div
      role="dialog"
      aria-modal="false"
      aria-label={`Product tour, step ${currentStep + 1} of ${steps.length}: ${step.title}`}
      aria-live="polite"
      className={cn(
        'w-full max-w-sm p-4 rounded-2xl bg-white dark:bg-[#131318] border border-black/10 dark:border-white/[0.06]',
        'shadow-[0_20px_48px_-10px_rgba(0,0,0,0.6)] backdrop-blur-xl animate-in fade-in zoom-in-95',
        className
      )}
    >
      {/* Header with step pill & close */}
      <div className="flex items-center justify-between pb-3">
        <span className="text-[11px] font-mono px-2 py-0.5 rounded-full bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 font-medium">
          Step {currentStep + 1} of {steps.length}
        </span>
        <button
          type="button"
          onClick={onDismiss}
          aria-label="Dismiss tour"
          className="p-1 rounded-lg text-zinc-400 hover:text-zinc-700 dark:hover:text-white transition-colors"
        >
          <X className="w-3.5 h-3.5" />
        </button>
      </div>

      {/* Step Content */}
      <div className="flex flex-col gap-1.5 pb-4">
        <h5 className="text-sm font-semibold text-zinc-900 dark:text-white flex items-center gap-1.5">
          <Sparkles className="w-3.5 h-3.5 text-amber-500" />
          {step.title}
        </h5>
        <p className="text-xs text-zinc-500 dark:text-zinc-400 leading-relaxed">
          {step.description}
        </p>
      </div>

      {/* Step Indicators & Actions */}
      <div className="flex items-center justify-between pt-2 border-t border-black/[0.04] dark:border-white/[0.04]">
        {/* Progress Dots */}
        <div className="flex items-center gap-1" role="progressbar" aria-valuemin={1} aria-valuemax={steps.length} aria-valuenow={currentStep + 1} aria-label={`Tour progress: step ${currentStep + 1} of ${steps.length}`}>
          {steps.map((_, idx) => (
            <div
              key={idx}
              aria-hidden="true"
              className={cn(
                'h-1.5 rounded-full transition-all duration-300',
                idx === currentStep
                  ? 'w-4 bg-zinc-900 dark:bg-white'
                  : 'w-1.5 bg-zinc-300 dark:bg-white/20'
              )}
            />
          ))}
        </div>

        {/* Buttons */}
        <div className="flex items-center gap-1.5">
          {currentStep > 0 && (
            <Button size="xs" variant="ghost" onClick={prev} aria-label="Previous step">
              <ChevronLeft className="w-3.5 h-3.5" />
            </Button>
          )}
          <Button
            size="xs"
            variant="primary"
            onClick={next}
            aria-label={isLast ? 'Finish tour' : 'Next step'}
            className="text-xs px-3"
          >
            <span>{isLast ? 'Finish' : 'Next'}</span>
            {isLast ? (
              <Check className="w-3 h-3 ml-1" />
            ) : (
              <ChevronRight className="w-3 h-3 ml-1" />
            )}
          </Button>
        </div>
      </div>
    </div>
  );
}

/**
 * UI99 — TreeView Component
 * Recursive hierarchical file and folder tree with chevron toggle, icons, and active node selection.
 *
 * A11y: WAI-ARIA tree pattern — role="tree"/"treeitem"/"group", aria-expanded on
 * folders, aria-selected on the active node, roving tabindex with arrow-key
 * navigation (Up/Down move, Right expands, Left collapses), Enter/Space select.
 */

import React, { useState, useRef, useCallback } from 'react';
import {
  ChevronRight,
  Folder,
  FolderOpen,
  FileCode,
  FileText,
  FileJson,
  Hash,
} from 'lucide-react';
import { cn } from '../../lib/utils';

export interface TreeNode {
  id: string;
  name: string;
  type: 'folder' | 'file';
  extension?: string;
  children?: TreeNode[];
}

export interface TreeViewProps {
  data: TreeNode[];
  selectedId?: string;
  onSelect?: (node: TreeNode) => void;
  className?: string;
  /** Accessible name for the tree region. */
  label?: string;
}

function getFileIcon(extension?: string) {
  switch (extension) {
    case 'tsx':
    case 'ts':
    case 'jsx':
    case 'js':
      return <FileCode className="w-3.5 h-3.5 text-blue-400" />;
    case 'json':
      return <FileJson className="w-3.5 h-3.5 text-amber-400" />;
    case 'css':
      return <Hash className="w-3.5 h-3.5 text-emerald-400" />;
    default:
      return <FileText className="w-3.5 h-3.5 text-zinc-400" />;
  }
}

interface TreeItemProps {
  node: TreeNode;
  selectedId?: string;
  onSelect?: (node: TreeNode) => void;
  level?: number;
  /** Shared registry of refs to every rendered row (flattened document order). */
  rowRefs: React.MutableRefObject<Map<string, HTMLDivElement>>;
  openState: Map<string, boolean>;
  toggleOpen: (id: string) => void;
}

function TreeItem({
  node,
  selectedId,
  onSelect,
  level = 0,
  rowRefs,
  openState,
  toggleOpen,
}: TreeItemProps) {
  const isFolder = node.type === 'folder';
  const isOpen = isFolder ? openState.get(node.id) ?? true : false;
  const isSelected = selectedId === node.id;

  const handleClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (isFolder) {
      toggleOpen(node.id);
    }
    onSelect?.(node);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      if (isFolder) toggleOpen(node.id);
      onSelect?.(node);
      return;
    }
    if (e.key === 'ArrowRight' && isFolder && !isOpen) {
      e.preventDefault();
      toggleOpen(node.id);
      return;
    }
    if (e.key === 'ArrowLeft' && isFolder && isOpen) {
      e.preventDefault();
      toggleOpen(node.id);
    }
  };

  const children = isFolder && isOpen ? node.children : undefined;

  return (
    <div className="flex flex-col select-none">
      <div
        ref={(el) => {
          if (el) rowRefs.current.set(node.id, el);
          else rowRefs.current.delete(node.id);
        }}
        role="treeitem"
        aria-level={level + 1}
        aria-selected={isSelected}
        aria-expanded={isFolder ? isOpen : undefined}
        tabIndex={-1}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        style={{ paddingLeft: `${level * 16 + 8}px` }}
        className={cn(
          'flex items-center gap-2 py-1.5 pr-2 rounded-xl text-xs font-mono transition-colors cursor-pointer outline-none',
          'focus-visible:ring-2 focus-visible:ring-emerald-500/60 focus-visible:ring-offset-1 focus-visible:ring-offset-transparent',
          isSelected
            ? 'bg-zinc-200 dark:bg-white/[0.08] text-zinc-950 dark:text-white font-semibold'
            : 'text-zinc-600 dark:text-zinc-400 hover:bg-zinc-100 dark:hover:bg-white/[0.03] hover:text-zinc-900 dark:hover:text-zinc-200'
        )}
      >
        {isFolder ? (
          <>
            <button
              type="button"
              aria-hidden="true"
              tabIndex={-1}
              onClick={(e) => {
                e.stopPropagation();
                toggleOpen(node.id);
              }}
              className="p-0.5 hover:bg-black/5 dark:hover:bg-white/5 rounded"
            >
              <ChevronRight
                className={cn('w-3.5 h-3.5 transition-transform duration-150', isOpen && 'rotate-90')}
              />
            </button>
            {isOpen ? (
              <FolderOpen className="w-3.5 h-3.5 text-amber-500 shrink-0" />
            ) : (
              <Folder className="w-3.5 h-3.5 text-amber-500 shrink-0" />
            )}
          </>
        ) : (
          <span className="w-3.5 h-3.5 shrink-0 ml-1">
            {getFileIcon(node.extension)}
          </span>
        )}
        <span className="truncate">{node.name}</span>
      </div>

      {children && (
        <div role="group" className="flex flex-col">
          {children.map((child) => (
            <TreeItem
              key={child.id}
              node={child}
              selectedId={selectedId}
              onSelect={onSelect}
              level={level + 1}
              rowRefs={rowRefs}
              openState={openState}
              toggleOpen={toggleOpen}
            />
          ))}
        </div>
      )}
    </div>
  );
}

export function TreeView({ data, selectedId, onSelect, className, label = 'File tree' }: TreeViewProps) {
  // Open-state is lifted so arrow-key collapse/expand stays in sync across rows.
  const [openState, setOpenState] = useState<Map<string, boolean>>(() => new Map());
  const rowRefs = useRef<Map<string, HTMLDivElement>>(new Map());

  const toggleOpen = useCallback((id: string) => {
    setOpenState((prev) => {
      const next = new Map(prev);
      next.set(id, !(prev.get(id) ?? true));
      return next;
    });
  }, []);

  /** Flattened visible row ids in document order — the navigation axis. */
  const getVisibleRowIds = useCallback((): string[] => {
    const ids: string[] = [];
    const walk = (nodes: TreeNode[]) => {
      for (const n of nodes) {
        ids.push(n.id);
        if (n.type === 'folder' && (openState.get(n.id) ?? true) && n.children) {
          walk(n.children);
        }
      }
    };
    walk(data);
    return ids;
  }, [data, openState]);

  const handleNavKey = useCallback(
    (e: React.KeyboardEvent) => {
      const rows = getVisibleRowIds();
      const current = document.activeElement as HTMLElement | null;
      const currentId = current?.getAttribute('data-tree-id') ?? undefined;
      // Fall back to first row when nothing is focused yet.
      const idx = currentId ? rows.findIndex((r) => {
        const el = rowRefs.current.get(r);
        return el === current;
      }) : -1;

      const focusRow = (id: string) => {
        const el = rowRefs.current.get(id);
        if (el) {
          el.focus();
          el.setAttribute('data-tree-id', id);
        }
      };

      if (e.key === 'ArrowDown') {
        e.preventDefault();
        const next = rows[Math.min(idx + 1, rows.length - 1)] ?? rows[0];
        if (next) focusRow(next);
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        const prev = rows[Math.max(idx - 1, 0)] ?? rows[0];
        if (prev) focusRow(prev);
      }
    },
    [getVisibleRowIds],
  );

  return (
    <div
      role="tree"
      aria-label={label}
      onKeyDown={handleNavKey}
      className={cn(
        'p-2 rounded-2xl bg-white dark:bg-[#0B0C11] border border-black/[0.06] dark:border-white/[0.04]',
        'flex flex-col gap-0.5 overflow-hidden',
        className
      )}
    >
      {data.map((node) => (
        <TreeItem
          key={node.id}
          node={node}
          selectedId={selectedId}
          onSelect={onSelect}
          level={0}
          rowRefs={rowRefs}
          openState={openState}
          toggleOpen={toggleOpen}
        />
      ))}
    </div>
  );
}

/**
 * UI99 — TrendDelta (Wave D)
 * Compact signed delta chip: +12.4% / -3.1% with semantic tone, used inside
 * tables, tiles and headers. Color never the only signal (icon + sign).
 */

import React from 'react';
import { ArrowUpRight, ArrowDownRight, Minus } from 'lucide-react';
import { cn } from '../../lib/utils';

export interface TrendDeltaProps {
  delta: number;
  suffix?: string;
  size?: 'sm' | 'md';
  showIcon?: boolean;
  invertTone?: boolean; // for "lower is better" metrics
  className?: string;
}

export function TrendDelta({
  delta,
  suffix = '%',
  size = 'sm',
  showIcon = true,
  invertTone = false,
  className = '',
}: TrendDeltaProps) {
  const effective = invertTone ? -delta : delta;
  const tone =
    effective > 0 ? 'up' : effective < 0 ? 'down' : 'flat';
  const toneStyle = {
    up: 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-400 border-emerald-500/20',
    down: 'bg-rose-500/10 text-rose-700 dark:text-rose-400 border-rose-500/20',
    flat: 'bg-black/[0.04] text-zinc-600 dark:bg-white/[0.05] dark:text-[#8E8E98] border-black/[0.04] dark:border-white/[0.05]',
  }[tone];
  const Icon = tone === 'up' ? ArrowUpRight : tone === 'down' ? ArrowDownRight : Minus;

  return (
    <span
      className={cn(
        'inline-flex items-center gap-0.5 rounded-full border font-mono font-semibold whitespace-nowrap',
        size === 'sm' ? 'px-1.5 py-0.5 text-[10px]' : 'px-2 py-1 text-xs',
        toneStyle,
        className
      )}
    >
      {showIcon && <Icon className={size === 'sm' ? 'w-3 h-3' : 'w-3.5 h-3.5'} aria-hidden="true" />}
      {delta > 0 ? '+' : ''}
      {delta}
      {suffix}
    </span>
  );
}

/**
 * UI99 UI Kit — Self-Contained Theme Detection (Phase 2.1)
 *
 * Kit primitives must not depend on app context (npm-package portability,
 * the shadcn/ui standard: copy a component anywhere and it works).
 *
 * The app shell (AppProvider) owns theme *state* and expresses it by toggling
 * the `dark` / `light` class on <html>. This hook observes that class with a
 * MutationObserver via useSyncExternalStore — no context needed, reactive to
 * app theme switches, SSR/JS-safe. Consumers can still force a mode with
 * `darkMode` prop overrides, matching shadcn's opt-out ergonomics.
 */

import { useSyncExternalStore } from 'react';

export type KitThemeMode = 'dark' | 'light';

function subscribe(onChange: () => void): () => void {
  if (typeof document === 'undefined') return () => {};
  const observer = new MutationObserver(onChange);
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ['class'],
  });
  return () => observer.disconnect();
}

function getSnapshot(): KitThemeMode {
  if (typeof document === 'undefined') return 'dark';
  return document.documentElement.classList.contains('light') ? 'light' : 'dark';
}

function getServerSnapshot(): KitThemeMode {
  // UI99 is dark-first (AGENTS.md §1)
  return 'dark';
}

export function useIsDark(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot) === 'dark';
}

export type ThemeOverride = KitThemeMode | undefined;

/** Convenience for primitives: resolve explicit prop override or observed mode. */
export function useThemeClass(darkMode?: ThemeOverride): { isDark: boolean; mode: KitThemeMode } {
  const observed = useIsDark();
  const mode: KitThemeMode = darkMode ?? (observed ? 'dark' : 'light');
  return { isDark: mode === 'dark', mode };
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Utility for combining Tailwind CSS classes with clsx and resolving conflicts with tailwind-merge.
 * Standard implementation benchmarked against shadcn/ui.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * UI99 UI Kit — `ui99.css` (source of truth, imported by src/index.css)
 *
 * Single source of truth for the kit's runtime design tokens.
 * Theme protocol: the app shell expresses theme by toggling `dark`/`light`
 * on <html>; tokens resolve through var() cascade.
 */

/* ======================= OBSIDIAN DARK (default) ======================= */
.dark {
  /* Surfaces with seamless velvet continuity (low-delta tonal progression) */
  --bg-canvas: #060709;
  --bg-surface: #090A0E;
  --bg-card: #0C0D12;
  --bg-card-hover: #101117;
  --bg-elevated: #111218;
  --bg-sunken: #07080B;
  --border-subtle: transparent;
  --border-strong: rgba(255, 255, 255, 0.05);
  --border-specular: rgba(255, 255, 255, 0.035);
  --border-hairline: rgba(255, 255, 255, 0.025);

  /* Text - High contrast WCAG 2.2 / APCA certified */
  --text-primary: #EDEDEF;
  --text-secondary: #92929B;
  --text-muted: #60606B;
  --text-on-fill: #060709;

  /* Dock / glass */
  --dock-bg: rgba(9, 10, 14, 0.75);
  --dock-border: rgba(255, 255, 255, 0.03);

  /* M3-grade unified state layers */
  --state-hover: rgba(255, 255, 255, 0.045);
  --state-press: rgba(255, 255, 255, 0.03);
  --state-selected: rgba(255, 255, 255, 0.06);
  --state-drag: rgba(255, 255, 255, 0.12);

  /* Focus (WCAG 2.4.11/2.4.13) */
  --focus-ring: rgba(16, 185, 129, 0.55);
}

/* ======================= PORCELAIN LIGHT ======================= */
.light {
  --bg-canvas: #F5F5F8;
  --bg-surface: #FFFFFF;
  --bg-card: #FFFFFF;
  --bg-card-hover: #F8F8FA;
  --bg-elevated: #FFFFFF;
  --bg-sunken: #F0F0F4;
  --border-subtle: rgba(0, 0, 0, 0.045);
  --border-strong: rgba(0, 0, 0, 0.12);
  --border-specular: rgba(255, 255, 255, 1);
  --border-hairline: rgba(0, 0, 0, 0.03);

  --text-primary: #111116;
  --text-secondary: #646470;
  --text-muted: #9494A0;
  --text-on-fill: #FFFFFF;

  --dock-bg: rgba(255, 255, 255, 0.94);
  --dock-border: rgba(0, 0, 0, 0.05);

  /* Light-mode calibrated state layers (subtle, non-glare) */
  --state-hover: rgba(0, 0, 0, 0.04);
  --state-press: rgba(0, 0, 0, 0.03);
  --state-selected: rgba(0, 0, 0, 0.06);
  --state-drag: rgba(0, 0, 0, 0.1);

  --focus-ring: rgba(5, 150, 105, 0.5);
}

/* ======================= SHARED / THEME-AGNOSTIC ======================= */
.dark,
.light {
  /* Motion durations (Apple HIG 150–500ms band) */
  --duration-instant: 75ms;
  --duration-fast: 120ms;
  --duration-base: 180ms;
  --duration-slow: 280ms;
  --duration-deliberate: 400ms;

  /* Easing curves */
  --ease-ui99: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-standard: cubic-bezier(0.2, 0, 0, 1);

  /* Typography */
  --font-sans: 'Geist', 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --font-mono: 'JetBrains Mono', 'Geist Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-persian: 'Vazirmatn', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  /* Radius scale (iOS 18+ smooth curves, mathematical nesting) */
  --radius-pill: 9999px;
  --radius-sheet: 32px;
  --radius-card-xl: 28px;
  --radius-card-lg: 24px;
  --radius-card-md: 18px;
  --radius-card-sm: 12px;
}

/* ======================= FOCUS UTILITIES (WCAG 2.4.13) ======================= */
/* Plain-CSS class form: safe to consume from the npm stylesheet without Tailwind. */

.focus-ui99:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--bg-canvas), 0 0 0 4px var(--focus-ring);
}

.focus-ui99-inset:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--focus-ring);
}

/* ======================= REDUCED MOTION ======================= */
@media (prefers-reduced-motion: reduce) {
  .dark *,
  .light * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/**
 * UI99 — `porcelain.css` (Theme Preset 2: Porcelain)
 *
 * A warmer, softer light theme: bone-white canvas, unglazed-ceramic
 * surfaces, ink-primary text. Engineered for the same audit bar as the
 * Obsidian pairing — body text ≥ 7:1 (AAA), secondary ≥ 4.5:1 (AA),
 * hairlines under perceptual-noise threshold.
 *
 * Usage: import once AFTER ui99.css, then toggle `.porcelain` on <html>.
 * The `.light` block in ui99.css remains the neutral light baseline;
 * porcelain overrides it for hosts that prefer warmth.
 */

.porcelain {
  /* Surfaces — bone canvas, ceramic cards */
  --bg-canvas: #FAF9F6;
  --bg-surface: #FFFFFF;
  --bg-card: #FFFFFF;
  --bg-card-hover: #F6F5F1;
  --bg-elevated: #FFFFFF;
  --bg-sunken: #F1F0EC;
  --border-subtle: rgba(28, 25, 23, 0.06);
  --border-strong: rgba(28, 25, 23, 0.13);
  --border-specular: rgba(255, 255, 255, 1);
  --border-hairline: rgba(28, 25, 23, 0.035);

  /* Text — ink on bone (contrast vs #FAF9F6) */
  --text-primary: #1C1917;      /* 15.8:1 AAA */
  --text-secondary: #57534E;    /* 6.9:1 AA+ */
  --text-muted: #79716B;        /* 4.6:1 AA */
  --text-on-fill: #FFFFFF;

  /* Dock / glass */
  --dock-bg: rgba(255, 255, 255, 0.82);
  --dock-border: rgba(28, 25, 23, 0.07);

  /* State layers (warm-tinted, M3 ratios) */
  --state-hover: rgba(28, 25, 23, 0.05);
  --state-press: rgba(28, 25, 23, 0.035);
  --state-selected: rgba(28, 25, 23, 0.07);
  --state-drag: rgba(28, 25, 23, 0.14);

  /* Focus — copper on porcelain */
  --focus-ring: rgba(180, 83, 9, 0.55);
}
